/** Set `DEBUG_VEHICLE_THUMBNAIL=1` (or `true`) for verbose thumbnail resolution logs. */
const DEBUG_VEHICLE_THUMBNAIL =
  process.env.DEBUG_VEHICLE_THUMBNAIL === '1' ||
  process.env.DEBUG_VEHICLE_THUMBNAIL === 'true';

function _snapshotVehicleMediaFields(vehicle) {
  if (!vehicle || typeof vehicle !== 'object') return {};
  const keys = Object.keys(vehicle).filter((k) =>
    /photo|image|thumb|url|picture|media|gallery/i.test(k)
  );
  const out = {};
  for (const k of keys) {
    const v = vehicle[k];
    if (v == null) out[k] = v;
    else if (typeof v === 'string') {
      out[k] =
        v.length > 200
          ? `${v.slice(0, 200)}…(string len=${v.length})`
          : v;
    } else if (Array.isArray(v)) {
      const first = v[0];
      let preview = first;
      if (first != null && typeof first === 'object') {
        preview = JSON.stringify(first);
      }
      const p =
        typeof preview === 'string' && preview.length > 120
          ? `${preview.slice(0, 120)}…`
          : preview;
      out[k] = { kind: 'array', length: v.length, first: p };
    } else if (typeof v === 'object') {
      out[k] = {
        kind: 'object',
        keys: Object.keys(v).slice(0, 25),
      };
    } else {
      out[k] = String(v);
    }
  }
  return out;
}

/**
 * First photo URL for inventory vehicle cards (DB + in-memory inventory shape).
 */
function getFirstVehicleThumbnailUrl(vehicle) {
  const debug = DEBUG_VEHICLE_THUMBNAIL;
  const vehicleLabel =
    vehicle && typeof vehicle === 'object'
      ? {
          id: vehicle.id,
          stock_number: vehicle.stock_number ?? vehicle.stockNumber,
          make: vehicle.make,
          model: vehicle.model,
        }
      : vehicle;

  if (!vehicle || typeof vehicle !== 'object') {
    if (debug) {
      console.warn('[getFirstVehicleThumbnailUrl] invalid vehicle', {
        vehicle: vehicleLabel,
        typeofVehicle: typeof vehicle,
      });
    }
    return null;
  }

  const rawList =
    vehicle.photo_url_list ??
    vehicle.photoUrlList ??
    vehicle.photo_urls ??
    vehicle.photoUrls ??
    vehicle.photos ??
    vehicle.images ??
    vehicle.image_urls ??
    vehicle.imageUrls;

  if (debug) {
    console.log('[getFirstVehicleThumbnailUrl] start', {
      vehicle: vehicleLabel,
      rawListSourceKey: [
        vehicle.photo_url_list != null ? 'photo_url_list' : null,
        vehicle.photoUrlList != null ? 'photoUrlList' : null,
        vehicle.photo_urls != null ? 'photo_urls' : null,
        vehicle.photoUrls != null ? 'photoUrls' : null,
        vehicle.photos != null ? 'photos' : null,
        vehicle.images != null ? 'images' : null,
        vehicle.image_urls != null ? 'image_urls' : null,
        vehicle.imageUrls != null ? 'imageUrls' : null,
      ].filter(Boolean),
      rawListType: rawList == null ? 'null/undefined' : Array.isArray(rawList) ? 'array' : typeof rawList,
      rawListPreview:
        typeof rawList === 'string'
          ? rawList.length > 300
            ? `${rawList.slice(0, 300)}…`
            : rawList
          : rawList,
    });
  }

  const coerceUrl = (v) => {
    if (!v) return null;
    if (typeof v === 'string') return v.trim() || null;
    if (typeof v === 'object') {
      const candidate =
        v.url ??
        v.src ??
        v.href ??
        v.location ??
        v.path ??
        v.image_url ??
        v.thumbnail_url;
      return typeof candidate === 'string' ? candidate.trim() || null : null;
    }
    return null;
  };

  const extractFirstUrl = (listValue) => {
    if (!listValue) return null;
    if (Array.isArray(listValue)) {
      for (const item of listValue) {
        const u = coerceUrl(item);
        if (u) return u;
      }
      return null;
    }
    if (typeof listValue === 'string') {
      const raw = listValue.trim();
      if (!raw) return null;

      // JSON array format: ["url1","url2"] or [{"url":"..."}, ...]
      if (raw.startsWith('[') && raw.endsWith(']')) {
        try {
          const parsed = JSON.parse(raw);
          return extractFirstUrl(parsed);
        } catch {
          // Fall through to other parsing heuristics
        }
      }

      // PostgreSQL array string format: {"url1","url2"}
      if (raw.startsWith('{') && raw.endsWith('}')) {
        const urls = raw
          .slice(1, -1)
          .split(',')
          .map((u) => u.trim().replace(/^"|"$/g, ''))
          .filter(Boolean);
        return urls.length > 0 ? urls[0] : null;
      }

      // Comma-separated URLs or paths
      if (raw.includes(',')) {
        const first = raw.split(',')[0]?.trim();
        return first || null;
      }

      // Single URL or asset path
      return raw;
    }
    if (typeof listValue === 'object') {
      // Some feeds use { urls: [...] } / { images: [...] } etc.
      const nested =
        listValue.urls ??
        listValue.images ??
        listValue.photos ??
        listValue.photo_url_list ??
        listValue.photoUrlList;
      return extractFirstUrl(nested) ?? coerceUrl(listValue);
    }
    return null;
  };

  const firstFromList = extractFirstUrl(rawList);
  if (firstFromList) {
    if (debug) {
      console.log('[getFirstVehicleThumbnailUrl] resolved from list/rawList', {
        vehicle: vehicleLabel,
        urlPreview:
          firstFromList.length > 120
            ? `${firstFromList.slice(0, 120)}…`
            : firstFromList,
      });
    }
    return firstFromList;
  }
  if (vehicle.image_url && typeof vehicle.image_url === 'string') {
    if (debug) {
      console.log('[getFirstVehicleThumbnailUrl] resolved image_url', { vehicle: vehicleLabel });
    }
    return vehicle.image_url;
  }
  if (vehicle.thumbnail_url && typeof vehicle.thumbnail_url === 'string') {
    if (debug) console.log('[getFirstVehicleThumbnailUrl] resolved thumbnail_url', { vehicle: vehicleLabel });
    return vehicle.thumbnail_url;
  }
  if (vehicle.thumbnailUrl && typeof vehicle.thumbnailUrl === 'string') {
    if (debug) console.log('[getFirstVehicleThumbnailUrl] resolved thumbnailUrl', { vehicle: vehicleLabel });
    return vehicle.thumbnailUrl;
  }
  if (vehicle.imageUrl && typeof vehicle.imageUrl === 'string') {
    if (debug) console.log('[getFirstVehicleThumbnailUrl] resolved imageUrl', { vehicle: vehicleLabel });
    return vehicle.imageUrl;
  }

  console.warn('[getFirstVehicleThumbnailUrl] NO_URL — check inventory shape / DB column', {
    vehicle: vehicleLabel,
    hint: 'Set DEBUG_VEHICLE_THUMBNAIL=1 for step-by-step logs.',
    mediaFields: _snapshotVehicleMediaFields(vehicle),
    rawListWasEmpty: rawList == null || rawList === '',
    rawListEmptyArray: Array.isArray(rawList) && rawList.length === 0,
  });
  return null;
}

