    this.settingsCacheLoaded = new Map(); // dealerId -> boolean (whether cache is loaded)
    this.ttsSettingsCache = new Map(); // dealerId -> TTS settings object
    this.apiKeysCache = new Map(); // dealerId -> API keys object
    
    // ✅ NEW: TTS generation cache to prevent duplicate calls
    this.ttsGenerationCache = new Map(); // text -> audioUrl to prevent duplicate generation
    
    // NEW: Chat history and context management
    this.chatHistory = new Map(); // sessionId -> conversation history
    this.contextVectorStore = new Map(); // sessionId -> vector store for context
    this.userPreferences = new Map(); // sessionId -> extracted user preferences
