    this.tasks = {};
    this.currentDealerId = null;
    
    // NEW: Conversation flow management
    this.conversationFlowManager = new ConversationFlowManager();
    
    // NEW: Agent selection system
    this.agentSelector = null;
    

    
    // Note: inventoryService will be set when OptimizedCrewAgentAI is initialized
    console.log('🔍 Debug: SlotManager initialized:', !!this.slotManager);
    
