      // Bind the executeSequentialProcess method to the sales crew
      this.salesCrew.executeSequentialProcess = this.executeSequentialProcess.bind(this);

      console.log('✅ Dealership sales crew initialized with 4 specialized agents (LangChain-based)');
      console.log('📊 Final Agent Status:');
      // console.log(`   Sales Consultant: ${this.agents.salesConsultant ? '✅' : '❌'}`);
