  // Execute sequential process for the sales crew (LangChain-based)
  async executeSequentialProcess(input) {
    try {
      console.log('🚀 Starting sequential sales crew process...');
      
      const { customer_message, customer_info, dealer_id, current_inventory, dealer_prompts } = input;
      
      // Step 1: Sales Consultant - Greet and recommend
      console.log('👨‍💼 Step 1: Sales Consultant processing...');
      const salesPrompt = this.buildAgentPrompt(
        this.agents.salesConsultant,
        customer_message,
        { current_inventory, dealer_prompts, customer_info }
      );
      const salesResponse = await this.crewAI.invoke(salesPrompt);
      
      // Step 2: Product Specialist - Demo and test drive
      console.log('🔧 Step 2: Product Specialist processing...');
      const productPrompt = this.buildAgentPrompt(
        this.agents.productSpecialist,
        customer_message,
        { salesResponse: salesResponse.content, current_inventory, dealer_prompts, customer_info }
      );
      const productResponse = await this.crewAI.invoke(productPrompt);
      
      // Step 3: Finance Manager - Financing options
      console.log('💰 Step 3: Finance Manager processing...');
      const financePrompt = this.buildAgentPrompt(
        this.agents.financeManager,
        customer_message,
        { salesResponse: salesResponse.content, productResponse: productResponse.content, current_inventory, dealer_prompts, customer_info }
      );
      const financeResponse = await this.crewAI.invoke(financePrompt);
      
      // Step 4: Service Advisor - Post-sale support
      console.log('🔧 Step 4: Service Advisor processing...');
      const servicePrompt = this.buildAgentPrompt(
        this.agents.serviceAdvisor,
        customer_message,
        { salesResponse: salesResponse.content, productResponse: productResponse.content, financeResponse: financeResponse.content, current_inventory, dealer_prompts, customer_info }
      );
      const serviceResponse = await this.crewAI.invoke(servicePrompt);
      
      // Combine all responses into a comprehensive answer
      const finalResponse = this.combineAgentResponses([
        { agent: 'Sales Consultant', response: salesResponse.content },
        { agent: 'Product Specialist', response: productResponse.content },
        { agent: 'Finance Manager', response: financeResponse.content },
        { agent: 'Service Advisor', response: serviceResponse.content }
      ]);
      
      console.log('✅ Sequential sales crew process completed');
      return finalResponse;
      
    } catch (error) {
      console.error('❌ Error in sequential process:', error);
      throw error;
    }
  }

  // Build prompt for a specific agent
