  // NEW: Check if we should show inventory based on budget + vehicle type combination
  shouldShowInventoryForBudget(userMessage, userPrefs) {
    // Check if user mentioned a budget in their message
    const budgetKeywords = ['budget', 'price', 'cost', 'afford', 'spend', 'bill', 'payment'];
    const hasBudgetMention = budgetKeywords.some(keyword => 
      userMessage.toLowerCase().includes(keyword)
    );
    
    // Check if we have vehicle type preference
    const hasVehicleType = userPrefs.vehicleType && userPrefs.vehicleType.length > 0;
    
    // Check if we have budget range preference
    const hasBudgetRange = userPrefs.budgetRange && userPrefs.budgetRange.minBudget;
    
    // Show inventory if: budget mentioned + vehicle type known + budget range known
    return hasBudgetMention && hasVehicleType && hasBudgetRange;
  }

