        model: model,
        year: null, // Not stored in current structure
        trim: null, // Not stored in current structure
        features: [], // Not stored in current structure
        color_tone: colorTone,
        
        // Rich context flags
        hasType: !!vehicleType,
        hasMake: !!make,
        hasModel: !!model,
        hasYear: false,
        hasTrim: false,
