// Helper function to validate test drive completion before stage advancement
function validateTestDriveCompletion(slots, conversationContext = null) {
  // Only validate test drive completion if we're actually in the test_drive stage
  const currentStage = slots.currentStep || slots.stage;
  
  if (currentStage === 'test_drive') {
    // ✅ FIXED: Check actual completion conditions in the correct data structure
    // First try to get data from conversation context if available
    let testDriveCompleted = false;
    
    if (conversationContext && conversationContext.Daivesteps?.[4]) {
      const step4 = conversationContext.Daivesteps[4];
      testDriveCompleted = 
        step4.stageCompleted === true ||
        step4.slots?.slotDetectionStatus === 'complete' ||
        (step4.slots?.test_drive_completed === true && step4.slots?.test_drive_review) ||
        step4.slots?.completion_status === 'completed';
    }
    
    // Fallback to checking slots object directly
    if (!testDriveCompleted) {
      testDriveCompleted = 
        // Check if test drive stage is marked as completed
        slots.stageCompleted === true ||
        // Check if test drive slots are complete
        slots.slotDetectionStatus === 'complete' ||
        // Check if test drive is completed and has review
        (slots.test_drive_completed === true && slots.test_drive_review) ||
        // Check in the test_drive sub-object
        slots.test_drive?.completion_status === 'completed' ||
                              slots.test_drive?.step === 'completed' ||
                              slots.test_drive?.deal_ready === true ||
                              slots.test_drive?.step === 'review_collected' ||
                              slots.test_drive?.hasConfirmedInterest === true ||
        slots.test_drive?.isScheduled === true;
    }
    
    if (!testDriveCompleted) {
      console.log('🚗 Test drive not completed - preventing stage advancement');
      console.log('🔍 Validation details:', {
        currentStage: currentStage,
        hasConversationContext: !!conversationContext,
        step4StageCompleted: conversationContext?.Daivesteps?.[4]?.stageCompleted,
        step4SlotStatus: conversationContext?.Daivesteps?.[4]?.slots?.slotDetectionStatus,
        step4TestDriveCompleted: conversationContext?.Daivesteps?.[4]?.slots?.test_drive_completed,
        step4TestDriveReview: conversationContext?.Daivesteps?.[4]?.slots?.test_drive_review,
        slotsStageCompleted: slots.stageCompleted,
        slotsSlotStatus: slots.slotDetectionStatus,
        slotsTestDriveCompleted: slots.test_drive_completed,
        slotsTestDriveReview: slots.test_drive_review,
        slotsKeys: Object.keys(slots)
      });
      return false;
    }
  }
  return true;
}

