// ✅ NEW: Journey Completion Strategy Implementation
class JourneyCompletionManager {
  constructor() {
    this.steps = [
      'inquiry',
      'lead_capture', 
      'vehicle_selection',
      'test_drive',
      'trade_evaluation',
      'qualification',
      'purchase_commitment',
      'vehicle_preparation',
      'finance_manager',
      'delivery',
      'csi_followup'
    ];
    
    // Define mandatory slots for each step (simplified to only budget and vehicle_type)
    this.mandatorySlots = {
      'inquiry': ['vehicle_type'],
      'lead_capture': ['budget'],
      'vehicle_selection': ['vehicle_selected'], // ✅ FIXED: Require vehicle selection before advancing
      'test_drive': [
        'customer_location_confirmed',
        'test_drive_offered',
        'test_drive_confirmed',
        'test_drive_review'
      ], // ✅ UPDATED: Minimal required slots - test_drive_scheduled or keys_delivered checked conditionally based on location
      'trade_evaluation': ['trade_in_inquiry'], // ✅ SIMPLIFIED: Only requires trade-in confirmation (yes/no)
      'qualification': ['credit_situation', 'credit_score'], // ✅ UPDATED: Require both credit_situation and credit_score for mandatory slot validation
      'purchase_commitment': ['purchase_decision', 'payment_mode'], // ✅ ENHANCED: Require both decision and payment method
      'vehicle_preparation': ['vehicle_ready'],
      'finance_manager': ['financing_approved'],
      'delivery': ['delivery_scheduled'],
      'csi_followup': ['follow_up_completed']
    };
  }

  // Check if a step is completed based on mandatory fields and customer affirmation
  isStepCompleted(stepName, conversationContext) {
    const stepData = this.getStepData(stepName, conversationContext);
    if (!stepData) return false;

    // Check mandatory fields are filled
    const mandatoryFields = this.getMandatoryFields(stepName);
    const hasAllFields = mandatoryFields.every(field => {
      return this.hasFieldValue(stepData, field);
    });

    // Check customer affirmation
    const hasAffirmation = this.hasCustomerAffirmation(stepName, conversationContext);

    // Check no fallback/rejection status
    const noRejection = !this.hasRejectionStatus(stepData);

    return hasAllFields && hasAffirmation && noRejection;
  }

  // Get step data from conversation context
  getStepData(stepName, conversationContext) {
    const stepNumber = this.getStepNumber(stepName);
    // Try both numeric key and full step key
    return conversationContext.Daivesteps?.[stepNumber] || 
           conversationContext.Daivesteps?.[`Step ${stepNumber} - ${this.getStepDisplayName(stepName)}`];
  }

  // Get mandatory fields for each step
  getMandatoryFields(stepName) {
    const mandatoryFields = {
      'inquiry': ['vehicle_type'], // Match with getNextEmptyMandatorySlot
      'lead_capture': ['budget', 'contact_info', 'customer_profile'],
      'vehicle_selection': ['make', 'model', 'features'],
      'test_drive': ['test_drive_preference'],
      'trade_evaluation': ['trade_in_inquiry'], // ✅ SIMPLIFIED: Only requires trade-in confirmation (yes/no)
      'qualification': ['credit_situation', 'credit_score'], // ✅ UPDATED: Require both credit_situation and credit_score for mandatory slot validation
      'purchase_commitment': ['purchase_timeline'],
      'vehicle_preparation': ['vehicle_prep_requirements'],
      'finance_manager': ['finance_preferences'],
      'delivery': ['delivery_schedule'],
      'csi_followup': ['follow_up_preferences']
    };
    return mandatoryFields[stepName] || [];
  }

  /**
   * ✅ NEW: Enhanced step completion validation with specific field checks
   */
  isStepCompletedEnhanced(stepName, conversationContext) {
    // 🚀 SIMPLIFIED: Directly check DAIVE structure instead of using getStepData
    const stepNumber = this.getStepNumber(stepName);
    const stepData = conversationContext.Daivesteps?.[stepNumber];
    
    console.log(`🔍 Checking step ${stepName} (${stepNumber}) completion:`, {
      stepData: stepData,
      hasStepData: !!stepData
    });

    // Step-specific completion logic
    switch (stepName) {
      case 'inquiry':
        return this.isInquiryStepCompleted(stepData, conversationContext);
      
      case 'lead_capture':
        return this.isLeadCaptureStepCompleted(stepData, conversationContext);
      
      case 'vehicle_selection':
        return this.isVehicleSelectionStepCompleted(stepData, conversationContext);
      
      case 'test_drive':
        return this.isTestDriveStepCompleted(stepData, conversationContext);
      
      case 'trade_evaluation':
        return this.isTradeEvaluationStepCompleted(stepData, conversationContext);
      
      case 'qualification':
        return this.isQualificationStepCompleted(stepData, conversationContext);
      
      case 'purchase_commitment':
        return this.isPurchaseCommitmentStepCompleted(stepData, conversationContext);
      
      default:
        // Fallback to original logic
        return this.isStepCompleted(stepName, conversationContext);
    }
  }

  /**
   * ✅ NEW: Check if inquiry step is completed
   */
  isInquiryStepCompleted(stepData, conversationContext) {
    // 🚀 UPDATED: Only require vehicle_type as per new mandatory slots configuration
    const step1 = conversationContext.Daivesteps?.[1];
    const hasVehicleType = step1?.vehicle_type || 
                          step1?.slots?.vehicle_type ||
                          stepData?.vehicle_type || 
                          stepData?.slots?.vehicle_type;
    
    console.log('🔍 Inquiry step completion check (simplified):', {
      stepData: stepData,
      hasVehicleType: hasVehicleType,
      daivesteps1: conversationContext.Daivesteps?.[1]
    });
    
    // ✅ UPDATED: Mark as completed if we have vehicle_type (only mandatory slot)
    const isCompleted = !!hasVehicleType;
    console.log('🔍 Inquiry step completion result:', isCompleted, { hasVehicleType });
    
    return isCompleted;
  }

  /**
   * ✅ NEW: Check if lead capture step is completed
   */
  isLeadCaptureStepCompleted(stepData, conversationContext) {
    // 🚀 UPDATED: Only require budget as per new mandatory slots configuration
    const step2 = conversationContext.Daivesteps?.[2];
    const hasBudget = step2?.slots?.budget?.target_price || 
                     step2?.slots?.budget?.max_price ||
                     step2?.slots?.budget?.has_budget ||
                     stepData?.budget?.target_price || 
                     stepData?.budget?.max_price ||
                     stepData?.budget?.has_budget ||
                     stepData?.slots?.budget?.target_price ||
                     stepData?.slots?.budget?.max_price ||
                     stepData?.slots?.budget?.has_budget;
    
    console.log('🔍 Lead capture step completion check (simplified):', {
      stepData: stepData,
      hasBudget: hasBudget,
      daivesteps2: conversationContext.Daivesteps?.[2]
    });
    
    // ✅ UPDATED: Mark as completed if we have budget (only mandatory slot)
    const isCompleted = !!hasBudget;
    console.log('🔍 Lead capture step completion result:', isCompleted, { hasBudget });
    
    return isCompleted;
  }

  /**
   * ✅ NEW: Check if user is requesting budget extension/renegotiation
   */
  isBudgetExtensionRequested(userMessage, conversationContext) {
    if (!userMessage) return false;
    
    const message = userMessage.toLowerCase();
    const budgetExtensionKeywords = [
      'increase budget', 'extend budget', 'raise budget', 'higher budget',
      'more budget', 'budget increase', 'can afford more', 'spend more',
      'increase my budget', 'extend my budget', 'raise my budget',
      'budget too low', 'need more money', 'can pay more',
      'flexible budget', 'budget flexibility', 'adjust budget',
      'revise budget', 'update budget', 'change budget',
      'want to increase', 'want to extend', 'want to raise',
      'can extend', 'can increase', 'can raise',
      'want to spend more', 'want to pay more', 'can spend more',
      'need to increase', 'need to extend', 'need to raise',
      'want to adjust', 'need to adjust', 'want to revise', 'need to revise'
    ];
    
    const hasBudgetKeywords = budgetExtensionKeywords.some(keyword => 
      message.includes(keyword)
    );
    
    // Also check for numerical budget increases
    const budgetIncreasePattern = /(?:budget|spend|afford|pay).*(?:increase|extend|raise|more|higher|up).*(?:\$|dollar|\d+)/i;
    const hasBudgetIncreasePattern = budgetIncreasePattern.test(message);
    
    return hasBudgetKeywords || hasBudgetIncreasePattern;
  }

  /**
   * ✅ NEW: Handle budget renegotiation in lead capture step
   */
  handleBudgetRenegotiation(conversationContext, userMessage, extractedBudget) {
    try {
      console.log('💰 Handling budget renegotiation request...');
      
      // Check if lead capture step is completed
      const leadCaptureStepKey = '2';
      const stepData = conversationContext.Daivesteps?.[leadCaptureStepKey];
      
      if (!stepData) {
        console.log('❌ Lead capture step data not found');
        return false;
      }
      
      // Check if step is already completed
      const isStepCompleted = stepData.status === 'Completed';
      
      if (!isStepCompleted) {
        console.log('ℹ️ Lead capture step not completed yet, proceeding with normal budget update');
        return false;
      }
      
      // Step is completed, check if user is requesting budget extension
      if (!this.isBudgetExtensionRequested(userMessage, conversationContext)) {
        console.log('ℹ️ No budget extension request detected, ignoring budget update');
        return false;
      }
      
      console.log('✅ Budget extension requested for completed lead capture step');
      
      // Update budget with new values
      if (extractedBudget) {
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.target_price', extractedBudget.target_price || extractedBudget.max_price);
        this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
        
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.max_price', extractedBudget.max_price || extractedBudget.target_price);
        this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
        
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.has_budget', true);
        this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
        
        // Add renegotiation flag
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.renegotiated', true);
        this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
        
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.renegotiated_at', new Date().toISOString());
        this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
        
        // ✅ NEW: Reset budget increase counter when customer actually increases budget
        conversationContext.budgetIncreaseCount = 0;
        console.log('✅ Budget increase counter reset after successful budget update');
        
        console.log('✅ Budget successfully renegotiated and updated');
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('❌ Error handling budget renegotiation:', error);
      return false;
    }
  }

  /**
   * ✅ NEW: Enhanced budget update logic with renegotiation support
   */
  updateBudgetWithRenegotiationCheck(conversationContext, userMessage, budgetData) {
    try {
      // First check if this is a budget renegotiation request
      const isRenegotiation = this.handleBudgetRenegotiation(conversationContext, userMessage, budgetData);
      
      if (isRenegotiation) {
        console.log('💰 Budget renegotiation handled successfully');
        return true;
      }
      
      // If not renegotiation, proceed with normal budget update
      const leadCaptureStepKey = '2';
      
      if (budgetData?.target_price) {
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.target_price', budgetData.target_price);
        this.updateStepCompletion(conversationContext, leadCaptureStepKey);
      }
      
      if (budgetData?.max_price) {
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.max_price', budgetData.max_price);
        this.updateStepCompletion(conversationContext, leadCaptureStepKey);
      }
      
      if (budgetData?.has_budget) {
        this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'slots.budget.has_budget', budgetData.has_budget);
        this.updateStepCompletion(conversationContext, leadCaptureStepKey);
      }
      
      // ✅ NEW: Reset budget increase counter when customer actually increases budget
      conversationContext.budgetIncreaseCount = 0;
      console.log('✅ Budget increase counter reset after successful budget update');
      
      return true;
    } catch (error) {
      console.error('❌ Error updating budget with renegotiation check:', error);
      return false;
    }
  }

  /**
   * ✅ NEW: Check if budget update should be allowed in current progression step
   */
  shouldAllowBudgetUpdate(conversationContext, userMessage) {
    try {
      const currentStep = conversationContext.currentJourneyStep;
      
      // Always allow budget updates in lead capture step
      if (currentStep === 'lead_capture') {
        return true;
      }
      
      // For other steps, only allow if it's a budget renegotiation request
      if (this.isBudgetExtensionRequested(userMessage, conversationContext)) {
        console.log('💰 Budget renegotiation request detected in progression step');
        return true;
      }
      
      // Check if we're in a step where budget changes are not appropriate
      const budgetRestrictedSteps = [
        'vehicle_selection', 'test_drive', 'trade_evaluation', 
        'qualification', 'purchase_commitment', 'vehicle_prep',
        'finance_manager', 'delivery', 'csi_followup'
      ];
      
      if (budgetRestrictedSteps.includes(currentStep)) {
        console.log(`⚠️ Budget update not allowed in ${currentStep} step unless renegotiation requested`);
        return false;
      }
      
      return true;
    } catch (error) {
      console.error('❌ Error checking budget update permission:', error);
      return false;
    }
  }

  /**
   * ✅ NEW: Enhanced budget update with progression step validation
   */
  updateBudgetWithProgressionCheck(conversationContext, userMessage, budgetData) {
    try {
      // Check if budget update is allowed in current progression step
      if (!this.shouldAllowBudgetUpdate(conversationContext, userMessage)) {
        console.log('🚫 Budget update blocked - not allowed in current progression step');
        return false;
      }
      
      // Use the enhanced budget update logic
      return this.updateBudgetWithRenegotiationCheck(conversationContext, userMessage, budgetData);
    } catch (error) {
      console.error('❌ Error updating budget with progression check:', error);
      return false;
    }
  }

  /**
   * ✅ NEW: Get budget renegotiation status for lead capture step
   */
  getBudgetRenegotiationStatus(conversationContext) {
    try {
      const leadCaptureStepKey = 'Step 2 - Lead Capture';
      const stepData = conversationContext.Daivesteps?.[leadCaptureStepKey];
      
      if (!stepData) {
        return {
          hasBudget: false,
          isRenegotiated: false,
          renegotiatedAt: null,
          currentBudget: null
        };
      }
      
      return {
        hasBudget: stepData.budget?.has_budget || stepData.slots?.budget?.has_budget || false,
        isRenegotiated: stepData.budget?.renegotiated || stepData.slots?.budget?.renegotiated || false,
        renegotiatedAt: stepData.budget?.renegotiated_at || stepData.slots?.budget?.renegotiated_at || null,
        currentBudget: {
          target_price: stepData.budget?.target_price || stepData.slots?.budget?.target_price || null,
          max_price: stepData.budget?.max_price || stepData.slots?.budget?.max_price || null
        }
      };
    } catch (error) {
      console.error('❌ Error getting budget renegotiation status:', error);
      return null;
    }
  }

  /**
   * ✅ NEW: Check if vehicle selection step is completed
   */
  isVehicleSelectionStepCompleted(stepData, conversationContext) {
    // 🚀 UPDATED: Only require vehicle_selected as per new mandatory slots configuration
    const step3 = conversationContext.Daivesteps?.[3];
    
    // Check for vehicle selection or inventory choice
    const hasSelection = stepData?.slots?.inventory_choice ||
                        stepData?.slots?.selectedVehicle ||
                        stepData?.slots?.VehicleSelection?.selectedVehicle ||
                        stepData?.slots?.vehicle_selected ||
                        conversationContext.Daivesteps?.[3]?.slots?.inventory_choice ||
                        conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection?.selectedVehicle ||
                        conversationContext.Daivesteps?.[3]?.slots?.vehicle_selected;
    
    console.log('🔍 Vehicle selection step completion check (simplified):', {
      stepData: stepData,
      hasSelection: hasSelection,
      daivesteps3: conversationContext.Daivesteps?.[3]
    });
    
    // ✅ UPDATED: Mark as completed if we have vehicle selection (only mandatory slot)
    const isCompleted = !!hasSelection;
    console.log('🔍 Vehicle selection step completion result:', isCompleted, { hasSelection });
    
    return isCompleted;
  }

  /**
   * ✅ NEW: Check if test drive step is completed
   */
  isTestDriveStepCompleted(stepData, conversationContext) {
    // 🚀 FIXED: Check DAIVE structure properly - Step 4 contains test drive info
    const step4 = conversationContext.Daivesteps?.[4];
    const hasConfirmation = step4?.test_drive?.hasConfirmedInterest ||
                           step4?.test_drive?.isScheduled ||
                           step4?.test_drive?.completion_status === 'completed' ||
                           stepData?.test_drive?.hasConfirmedInterest ||
                           stepData?.test_drive?.isScheduled ||
                           stepData?.test_drive?.completion_status === 'completed';
    
    const hasCompletion = step4?.test_drive?.step === 'completed' ||
                         step4?.test_drive?.deal_ready === true ||
                         stepData?.test_drive?.step === 'completed' ||
                         stepData?.test_drive?.deal_ready === true;
    
    const isCompleted = !!(hasConfirmation || hasCompletion);
    console.log('🔍 Test drive step completion check:', {
      hasConfirmation: hasConfirmation,
      hasCompletion: hasCompletion,
      isCompleted: isCompleted,
      test_drive: stepData?.test_drive,
      daivesteps4: conversationContext.Daivesteps?.[4]
    });
    
    return isCompleted;
  }

  /**
   * ✅ NEW: Check if trade evaluation step is completed
   */
  isTradeEvaluationStepCompleted(stepData, conversationContext) {
    // First, check if the step status is already marked as 'completed' or 'Completed'
    if (stepData?.status === 'completed' || stepData?.status === 'Completed') {
      return true;
    }
    
    // Check if trade-in was declined (step completed)
    if (stepData?.trade_in?.declined === true || stepData?.trade_in?.intent === false) {
      return true;
    }
    
    // Check if trade-in details were provided (step completed)
    if (stepData?.trade_in?.details_provided === true && stepData?.trade_in?.vehicle_info) {
      return true;
    }
    
    // Check for trade-in evaluation in slots (actual data structure from logs)
    const hasTradeEvaluated = stepData?.slots?.trade_in_evaluated === true ||
                              stepData?.slots?.trade_in_details ||
                              stepData?.slots?.tradeEvaluation;
    
    // Check for trade-in vehicle information in slots
    const hasTradeVehicle = stepData?.slots?.trade_in_vehicle ||
                           stepData?.slots?.trade_in_details ||
                           stepData?.trade_in?.vehicle_info;
    
    // Check if we have trade-in details populated
    const hasTradeDetails = stepData?.slots?.trade_in_make ||
                           stepData?.slots?.trade_in_model ||
                           stepData?.slots?.trade_in_year;
    
    return hasTradeEvaluated || hasTradeVehicle || hasTradeDetails;
  }

  /**
   * ✅ NEW: Check if qualification step is completed
   */
  isQualificationStepCompleted(stepData, conversationContext) {
    // ✅ UPDATED: Check for credit_situation OR credit_identified as primary completion indicator
    const hasCreditSituation = stepData?.slots?.qualification?.credit_situation ||
                              stepData?.qualification?.credit_situation ||
                              stepData?.slots?.qualification?.credit_identified === true ||
                              stepData?.slots?.qualification?.credit_score;
    
    if (hasCreditSituation) {
      return true;
    }
    
    // Fallback: Check if financing method is selected (cash, finance, or lease)
    if (stepData?.finance?.preferred_method || stepData?.finance?.mode || stepData?.slots?.finance?.preferred_method) {
      return true;
    }
    
    // Check if down payment is provided (implies financing)
    if (stepData?.slots?.finance?.down_payment || stepData?.slots?.finance?.down_payment_provided) {
      return true;
    }
    
    // Check for other qualification information
    const hasQualification = stepData?.slots?.qualification ||
                            stepData?.qualification?.employment_status ||
                            stepData?.qualification?.financing_method;
    
    return !!hasQualification;
  }

  /**
   * ✅ NEW: Check if purchase commitment step is completed
   */
  isPurchaseCommitmentStepCompleted(stepData, conversationContext) {
    // Check if purchase decision is made (yes or no)
    if (stepData?.purchase?.decision === 'yes' || stepData?.purchase?.committed === true) {
      return true;
    }
    
    // Check for purchase timeline or commitment
    const hasTimeline = stepData?.slots?.purchase_timeline ||
                       stepData?.purchase_commitment?.timeline ||
                       stepData?.purchase?.timeline;
    
    const hasCommitment = stepData?.purchase_commitment?.isCommitted ||
                         stepData?.slots?.purchase_commitment ||
                         stepData?.purchase?.ready_to_buy;
    
    return !!(hasTimeline || hasCommitment);
  }

  // Check if field has value
  hasFieldValue(stepData, fieldPath) {
    // Handle special cases for step-specific fields
    if (fieldPath === 'vehicle_type') {
      const vehicleType = stepData?.slots?.vehicle_type || 
                         stepData?.slots?.['VehicleSelection']?.type ||
                         stepData?.vehicle?.type;
      return vehicleType && vehicleType !== '' && vehicleType !== null && vehicleType !== undefined;
    }
    
    if (fieldPath === 'budget') {
      const budget = stepData?.slots?.budget?.max_price || 
                    stepData?.slots?.budget?.target_price ||
                    stepData?.budget?.max_price ||
                    stepData?.budget?.target_price;
      return budget && budget !== '' && budget !== null && budget !== undefined;
    }
    
    if (fieldPath === 'make') {
      const make = stepData?.slots?.['VehicleSelection']?.make || 
                  stepData?.slots?.vehicle?.make ||
                  stepData?.vehicle?.make;
      return make && make !== '' && make !== null && make !== undefined;
    }
    
    if (fieldPath === 'model') {
      const model = stepData?.slots?.['VehicleSelection']?.model || 
                   stepData?.slots?.vehicle?.model ||
                   stepData?.vehicle?.model;
      return model && model !== '' && model !== null && model !== undefined;
    }
    
      if (fieldPath === 'credit_situation') {
        const creditSituation = stepData?.slots?.qualification?.credit_situation ||
                              stepData?.qualification?.credit_situation ||
                              stepData?.slots?.qualification?.credit_identified === true ||
                              stepData?.slots?.qualification?.credit_score;
        return creditSituation && creditSituation !== '' && creditSituation !== null && creditSituation !== undefined;
      }
    
    if (fieldPath === 'credit_score') {
      const creditScore = stepData?.slots?.qualification?.credit_score ||
                        stepData?.qualification?.credit_score;
      return creditScore && creditScore !== '' && creditScore !== null && creditScore !== undefined;
    }
    
    if (fieldPath === 'purchase_decision') {
      const purchaseDecision = stepData?.slots?.purchase_commitment?.purchase_decision ||
                             stepData?.slots?.purchase_decision ||
                             stepData?.purchase_decision;
      return purchaseDecision && purchaseDecision !== '' && purchaseDecision !== null && purchaseDecision !== undefined;
    }
    
    if (fieldPath === 'payment_mode') {
      const paymentMode = stepData?.slots?.purchase_commitment?.payment_mode ||
                         stepData?.slots?.payment_mode ||
                         stepData?.payment_mode ||
                         stepData?.slots?.purchase_commitment?.payment_method ||
                         stepData?.slots?.payment_method ||
                         stepData?.payment_method ||
                         stepData?.slots?.finance?.preferred_method;
      return paymentMode && paymentMode !== '' && paymentMode !== null && paymentMode !== undefined;
    }
    
    // For other fields, use the original logic
    const parts = fieldPath.split('.');
    let current = stepData;
    for (const part of parts) {
      if (current && typeof current === 'object' && part in current) {
        current = current[part];
      } else {
        return false;
      }
    }
    return current !== null && current !== undefined && current !== '';
  }

  // Check for customer affirmation
  hasCustomerAffirmation(stepName, conversationContext) {
    const lastMessage = conversationContext.messages?.[conversationContext.messages.length - 1];
    if (!lastMessage || lastMessage.role !== 'user') return false;

    // For inquiry step, providing vehicle type is considered affirmation
    if (stepName === 'inquiry') {
      const message = lastMessage.content.toLowerCase();
      const vehicleTypes = ['suv', 'sedan', 'truck', 'car', 'vehicle', 'hybrid', 'electric', 'ev'];
      return vehicleTypes.some(type => message.includes(type));
    }

    // For other steps, use traditional affirmation patterns
    const affirmationPatterns = [
      /^(yes|yeah|yep|sure|okay|ok|alright|absolutely|definitely|of course|i like|i want|i'm interested|let's do|go ahead|proceed)/i,
      /(sounds good|that works|perfect|great|excellent|i agree|i accept)/i
    ];

    const message = lastMessage.content.toLowerCase();
    return affirmationPatterns.some(pattern => pattern.test(message));
  }

  // Check for rejection status
  hasRejectionStatus(stepData) {
    return stepData?.status === 'rejected' || stepData?.status === 'fallback';
  }

  // REMOVED: Duplicate getStepNumber and getStepDisplayName methods - using the ones below

  // Update step completion status
  updateStepCompletion(stepName, conversationContext, isCompleted) {
    if (conversationContext.stepCompleted) {
      conversationContext.stepCompleted[stepName] = isCompleted;
      conversationContext.last_updated = new Date().toISOString();
    }
  }

  // Get next incomplete step
  getNextIncompleteStep(conversationContext) {
    for (const step of this.steps) {
      if (!conversationContext.stepCompleted?.[step]) {
        return step;
      }
    }
    return null; // All steps completed
  }
  // ✅ NEW: Check if mandatory slots are completed for a step
  areMandatorySlotsCompleted(conversationContext, stepName) {
    const requiredSlots = this.mandatorySlots[stepName] || [];
    if (requiredSlots.length === 0) {
      return true; // No mandatory slots = always completed
    }
    
    // Check if all mandatory slots are filled
    return requiredSlots.every(slot => {
      return this.hasSlotValue(conversationContext, slot);
    });
  }
  
  // ✅ NEW: Check if a specific slot has a value
  hasSlotValue(conversationContext, slotName) {
    // Check in Daivesteps structure
    const step1 = conversationContext.Daivesteps?.[1];
    const step2 = conversationContext.Daivesteps?.[2];
    const step3 = conversationContext.Daivesteps?.[3];
    const step4 = conversationContext.Daivesteps?.[4];
    const step5 = conversationContext.Daivesteps?.[5];
    const step6 = conversationContext.Daivesteps?.[6];
    
    switch (slotName) {
      case 'vehicle_type':
        // Check multiple locations: step1.vehicle_type, step3.VehicleSelection.type, and context preferences
        const step1Type = step1?.vehicle_type || step1?.slots?.vehicle_type;
        const step3Type = step3?.slots?.VehicleSelection?.type;
        const contextType = step2?.slots?.preferences?.requirements?.vehicleType;
        return !!(step1Type || step3Type || contextType);
      case 'budget':
        // Check budget from slots location (step2.slots.budget)
        const budget = step2?.slots?.budget?.target_price || step2?.slots?.budget?.max_price;
        return !!budget;
      case 'vehicle_condition':
        return !!(step1?.vehicle_condition || step1?.slots?.vehicle_condition);
      case 'make':
        return !!(step3?.slots?.VehicleSelection?.make || step1?.make);
      case 'model':
        return !!(step3?.slots?.VehicleSelection?.model || step1?.model);
      case 'color_tone':
        return !!(step3?.slots?.VehicleSelection?.color_tone || step1?.color_tone);
      case 'test_drive_scheduled':
        return !!(step4?.test_drive?.is_scheduled || step4?.test_drive?.scheduled_date || step4?.slots?.test_drive_scheduled);
      case 'customer_at_location':
        return !!(step4?.slots?.customer_at_location);
      case 'customer_not_at_location':
        return !!(step4?.slots?.customer_not_at_location);
      case 'customer_location_confirmed':
        // ✅ FIXED: Either at location OR not at location counts as location confirmed
        return !!(step4?.slots?.customer_at_location || step4?.slots?.customer_not_at_location);
      case 'test_drive_offered':
        return !!(step4?.slots?.test_drive_offered);
      case 'test_drive_confirmed':
        return !!(step4?.slots?.test_drive_confirmed);
      case 'test_drive_review':
        return !!(step4?.slots?.test_drive_review);
      case 'vehicle_selected':
        // ✅ FIXED: Check for vehicle_selected slot in step3
        return !!(step3?.slots?.vehicle_selected || step3?.slots?.VehicleSelection?.hasSelectedVehicle || step3?.slots?.selectedVehicles?.length > 0);
      case 'trade_in_inquiry':
        // ✅ FIXED: Check for trade-in inquiry completion (yes/no response)
        const step5 = conversationContext.Daivesteps?.[5];
        return !!(step5?.slots?.trade_in_confirmed || step5?.slots?.trade_in_declined || step5?.trade_in?.declined !== undefined || step5?.slots?.trade_in_inquiry);
      case 'trade_in_value':
        return !!(step5?.trade_in?.estimated_value || step5?.slots?.trade_in_value);
        case 'credit_situation':
          return !!(step6?.slots?.qualification?.credit_situation || 
                   step6?.slots?.qualification?.credit_identified === true ||
                   step6?.slots?.qualification?.credit_score);    
      case 'credit_score':
        return !!(step6?.slots?.qualification?.credit_score );
      case 'purchase_decision':
        return !!(conversationContext.Daivesteps?.[7]?.purchase_decision || conversationContext.Daivesteps?.[7]?.slots?.purchase_decision);
      case 'payment_mode':
        return !!(conversationContext.Daivesteps?.[7]?.slots?.purchase_commitment?.payment_mode ||
                 conversationContext.Daivesteps?.[7]?.slots?.payment_mode ||
                 conversationContext.Daivesteps?.[7]?.slots?.purchase_commitment?.payment_method ||
                 conversationContext.Daivesteps?.[7]?.slots?.payment_method ||
                 conversationContext.Daivesteps?.[6]?.slots?.finance?.preferred_method);
      case 'vehicle_ready':
        return !!(conversationContext.Daivesteps?.[8]?.vehicle_ready || conversationContext.Daivesteps?.[8]?.slots?.vehicle_ready);
      case 'financing_approved':
        return !!(conversationContext.Daivesteps?.[9]?.financing_approved || conversationContext.Daivesteps?.[9]?.slots?.financing_approved);
      case 'delivery_scheduled':
        return !!(conversationContext.Daivesteps?.[10]?.delivery_scheduled || conversationContext.Daivesteps?.[10]?.slots?.delivery_scheduled);
      case 'follow_up_completed':
        return !!(conversationContext.Daivesteps?.[11]?.follow_up_completed || conversationContext.Daivesteps?.[11]?.slots?.follow_up_completed);
      default:
        return false;
    }
  }
  
  // ✅ NEW: Get step number from step name
  getStepNumber(stepName) {
    const stepMapping = {
      'inquiry': 1,
      'lead_capture': 2,
      'vehicle_selection': 3,
      'test_drive': 4,
      'trade_evaluation': 5,
      'qualification': 6,
      'purchase_commitment': 7,
      'vehicle_preparation': 8,
      'finance_manager': 9,
      'delivery': 10,
      'csi_followup': 11
    };
    return stepMapping[stepName] || 1;
  }
  
  // ✅ NEW: Get step display name
  getStepDisplayName(stepName) {
    const displayNames = {
      'inquiry': 'Inquiry',
      'lead_capture': 'Lead Capture',
      'vehicle_selection': 'Vehicle Selection',
      'test_drive': 'Test Drive',
      'trade_evaluation': 'Trade Evaluation',
      'qualification': 'Qualification',
      'purchase_commitment': 'Purchase Commitment',
      'vehicle_preparation': 'Vehicle Preparation',
      'finance_manager': 'Finance Manager',
      'delivery': 'Delivery',
      'csi_followup': 'CSI Follow-up'
    };
    return displayNames[stepName] || 'Unknown Step';
  }
}

// ✅ NEW: Vehicle Rejection Strategy Implementation
class VehicleRejectionManager {
  constructor() {
    this.resetSteps = [
      'vehicle_selection',
      'test_drive', 
      'purchase_commitment',
      'delivery',
      'finance'
    ];
    
    this.preserveSteps = [
      'budget',
      'vehicleCondition', 
      'preferred_features',
      'customerPreferences'
    ];
  }

  // Handle vehicle rejection and reset appropriate steps
  handleVehicleRejection(conversationContext, rejectedVehicle, reason) {
    console.log(`🚫 Vehicle rejected: ${rejectedVehicle.make} ${rejectedVehicle.model} - ${reason}`);
    
    // Add to rejected vehicles array
    this.addToRejectedVehicles(conversationContext, rejectedVehicle, reason);
    
    // Reset dependent steps
    this.resetDependentSteps(conversationContext);
    
    // Update current journey step back to vehicle selection
    conversationContext.currentJourneyStep = 'vehicle_selection';
    conversationContext.Currentstep = 'Vehicle Selection';
    
    // Clear current vehicle selection
    this.clearCurrentVehicleSelection(conversationContext);
    
    console.log('🔄 Steps reset after vehicle rejection');
  }

  // Add vehicle to rejected list
  addToRejectedVehicles(conversationContext, vehicle, reason) {
    const rejectedVehicle = {
      stock_number: vehicle.stock_number || vehicle.id || 'N/A',
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      price: vehicle.price,
      reason: reason,
      rejected_at: new Date().toISOString()
    };

    // Add to 3 Selection rejectedVehicles array
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (vehicleStep?.slots) {
      if (!Array.isArray(vehicleStep.slots.rejectedVehicles)) {
        vehicleStep.slots.rejectedVehicles = [];
      }
      vehicleStep.slots.rejectedVehicles.push(this._slimVehicle(rejectedVehicle));
    }
  }

  // Reset dependent steps after vehicle rejection
  resetDependentSteps(conversationContext) {
    this.resetSteps.forEach(step => {
      if (conversationContext.stepCompleted) {
        conversationContext.stepCompleted[step] = false;
      }
      
      // Reset step data
      this.resetStepData(conversationContext, step);
    });
  }

  // Reset specific step data
  resetStepData(conversationContext, stepName) {
    const stepNumber = this.getStepNumber(stepName);
    const stepKey = `Step ${stepNumber} - ${this.getStepDisplayName(stepName)}`;
    
    if (conversationContext.Daivesteps?.[stepKey]) {
      // Reset status to pending
      if (conversationContext.Daivesteps[stepKey].status) {
        conversationContext.Daivesteps[stepKey].status = 'Pending';
      }
      
      // Reset specific step data
      switch (stepName) {
        case 'vehicle_selection':
          conversationContext.Daivesteps[stepKey].slots.inventory_choice = null;
          conversationContext.Daivesteps[stepKey].slots.currentVehicle = null;
          break;
        case 'test_drive':
          conversationContext.Daivesteps[stepKey].test_drive = {
            hasConfirmedInterest: false,
            step: 'initial',
            timestamp: null,
            isImmediate: false,
            scheduled_day: null,
            scheduled_time: null,
            location: null,
            preferred_contact_method: null,
            confirmation_status: 'pending',
            notes: null,
            stageCompleted: {
              interest_confirmed: false,
              appointment_day_selected: false,
              appointment_time_selected: false,
              location_confirmed: false,
              confirmation_sent: false,
              status: 'Pending'
            }
          };
          break;
        case 'purchase_commitment':
          conversationContext.Daivesteps[stepKey].purchase_commitment = {
            isCommitted: false,
            expected_commitment_date: null,
            remarks: 'Awaiting new vehicle selection before commitment.',
            status: 'Pending'
          };
          break;
      }
    }
  }

  // Clear current vehicle selection
  clearCurrentVehicleSelection(conversationContext) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (vehicleStep?.slots) {
      vehicleStep.slots.inventory_choice = null;
      vehicleStep.slots.currentVehicle = null;
    }
  }

  // REMOVED: Duplicate getStepNumber and getStepDisplayName methods - using the ones below
}

// ✅ NEW: Array Tracking Manager
class ArrayTrackingManager {
  constructor() {
    this.arrays = {
      sharedVehicles: 'sharedVehicles',
      rejectedVehicles: 'rejectedVehicles', 
      selectedVehicles: 'selectedVehicles'
    };
  }

  // Fast-track feature response system
  isFeatureQuestion(userMessage, conversationContext) {
    // 🚫 DISABLED: Always return false to prevent fast-track feature responses
    return false;
    
    // Original logic commented out:
    if (!userMessage) return false;
    
    const message = userMessage.toLowerCase();
    const featureKeywords = [
      'features', 'feature', 'specifications', 'specs', 'spec',
      'mileage', 'mpg', 'fuel economy', 'gas mileage',
      'engine', 'transmission', 'horsepower', 'torque',
      'safety', 'airbag', 'backup camera', 'bluetooth',
      'navigation', 'gps', 'infotainment', 'audio',
      'seating', 'cargo', 'space', 'capacity',
      'warranty', 'maintenance', 'service',
      'color', 'exterior', 'interior', 'trim',
      'wheels', 'tires', 'brakes', 'suspension',
      'technology', 'connectivity', 'entertainment',
      'comfort', 'convenience', 'luxury'
    ];
    
    const hasFeatureKeywords = featureKeywords.some(keyword => message.includes(keyword));
    
    // Check if there are shared or selected vehicles to discuss
    const hasVehicles = this.hasVehiclesToDiscuss(conversationContext);
    
    return hasFeatureKeywords && hasVehicles;
  }

  hasVehiclesToDiscuss(conversationContext) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (!vehicleStep?.slots) return false;
    
    const sharedVehicles = vehicleStep.slots.sharedVehicles || [];
    const selectedVehicles = vehicleStep.slots.selectedVehicles || [];
    const inventoryData = vehicleStep.slots.inventoryData || [];
    
    return sharedVehicles.length > 0 || selectedVehicles.length > 0 || inventoryData.length > 0;
  }

  async generateFastFeatureResponse(userMessage, conversationContext) {
    try {
      console.log('🚀 FAST-TRACK: Generating feature response...');
      
      const vehicleStep = conversationContext.Daivesteps?.[3];
      const sharedVehicles = vehicleStep?.slots?.sharedVehicles || [];
      const selectedVehicles = vehicleStep?.slots?.selectedVehicles || [];
      const inventoryData = vehicleStep?.slots?.inventoryData || [];
      
      // Determine which vehicles to discuss
      let vehiclesToDiscuss = [];
      if (selectedVehicles.length > 0) {
        vehiclesToDiscuss = selectedVehicles;
        console.log('📋 Discussing selected vehicles:', selectedVehicles.length);
      } else if (sharedVehicles.length > 0) {
        vehiclesToDiscuss = sharedVehicles;
        console.log('📋 Discussing shared vehicles:', sharedVehicles.length);
      } else if (inventoryData.length > 0) {
        vehiclesToDiscuss = inventoryData.slice(0, 3);
        console.log('📋 Discussing inventory vehicles:', vehiclesToDiscuss.length);
      }
      
      if (vehiclesToDiscuss.length === 0) {
        return "I don't have any vehicles to discuss features for. Let me show you some options first!";
      }
      
      // Generate feature response using AI
      const featureResponse = await this.generateVehicleFeatureResponse(userMessage, vehiclesToDiscuss);
      
      console.log('✅ Fast-track feature response generated');
      return featureResponse;
      
    } catch (error) {
      console.error('❌ Error in fast-track feature response:', error);
      return "I'd be happy to discuss vehicle features! Let me show you some options first.";
    }
  }

  async generateVehicleFeatureResponse(userMessage, vehicles) {
    try {
      if (!this.optimizedCrewAI?.llm) {
        console.log('⚠️ LLM not available, using fallback response');
        return this.generateFallbackFeatureResponse(vehicles);
      }
      
      const vehicleDetails = vehicles.map((vehicle, index) => {
        return `${index + 1}. ${vehicle.year || 'N/A'} ${vehicle.make || 'N/A'} ${vehicle.model || 'N/A'} ${vehicle.trim || ''}
   - Price: $${vehicle.price?.toLocaleString() || 'Contact for pricing'}
   - Color: ${vehicle.color || 'N/A'}
   - Mileage: ${vehicle.mileage ? vehicle.mileage.toLocaleString() + ' miles' : 'N/A'}
   - Stock#: ${vehicle.stock_number || 'N/A'}
   - Features: ${vehicle.features ? vehicle.features.slice(0, 10).join(', ') : 'Standard features available'}`;
      }).join('\n\n');
      
      const prompt = `You are a helpful car sales assistant. The customer is asking about features of these vehicles:

${vehicleDetails}

Customer Question: "${userMessage}"

Please provide a BRIEF, CONCISE response about the vehicle features. Focus on:
- Top 3-4 key features only
- Brief mention of safety/technology
- Keep it under 60 words
- Be direct and to the point

Example format: "The [Year] [Make] [Model] features [key feature 1], [key feature 2], and [key feature 3]. It includes [safety/tech feature] and [comfort feature]. Perfect for [use case]!"`;

      const response = await this.optimizedCrewAI.llm.invoke(prompt);
      return response.content || response;
      
    } catch (error) {
      console.error('❌ Error generating AI feature response:', error);
      return this.generateFallbackFeatureResponse(vehicles);
    }
  }

  generateFallbackFeatureResponse(vehicles) {
    if (vehicles.length === 0) return "I don't have vehicle details to share right now.";
    
    const vehicle = vehicles[0]; // Focus on first vehicle
    let response = `The ${vehicle.year || ''} ${vehicle.make || ''} ${vehicle.model || ''} features `;
    
    if (vehicle.features && vehicle.features.length > 0) {
      response += `${vehicle.features.slice(0, 3).join(', ')}`;
      if (vehicle.features.length > 3) {
        response += ` and more`;
      }
    } else {
      response += `standard features`;
    }
    
    response += `. Price: $${vehicle.price?.toLocaleString() || 'Contact for pricing'}`;
    
    if (vehicle.mileage) {
      response += `, ${vehicle.mileage.toLocaleString()} miles`;
    }
    
    response += `. Would you like to test drive it?`;
    
    return response;
  }

  // Add multiple vehicles to shared vehicles array
  addVehiclesToSharedArray(conversationContext, vehicles) {
    if (!vehicles || !Array.isArray(vehicles)) return;
    
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (!vehicleStep?.slots) return;
    
    if (!Array.isArray(vehicleStep.slots.sharedVehicles)) {
      vehicleStep.slots.sharedVehicles = [];
    }
    
    vehicles.forEach(vehicle => {
      // Check if vehicle already exists
      const exists = vehicleStep.slots.sharedVehicles.some(v => 
        v.stock_number === vehicle.stock_number || 
        (v.make === vehicle.make && v.model === vehicle.model && v.year === vehicle.year)
      );
      
      if (!exists) {
        vehicleStep.slots.sharedVehicles.push({
          stock_number: vehicle.stock_number || vehicle.id || 'N/A',
          make: vehicle.make,
          model: vehicle.model,
          year: vehicle.year,
          trim: vehicle.trim,
          price: vehicle.price,
          color: vehicle.colors?.[0] || vehicle.color || 'N/A',
          mileage: vehicle.mileage,
          condition: vehicle.condition,
          id: vehicle.id
        });
        console.log(`✅ Added ${vehicle.make} ${vehicle.model} to shared vehicles`);
      }
    });
    
    console.log(`📊 Total shared vehicles: ${vehicleStep.slots.sharedVehicles.length}`);
  }

  handleVehicleRejection(conversationContext, rejectedVehicles) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (!vehicleStep?.slots) return;
    
    if (!Array.isArray(vehicleStep.slots.rejectedVehicles)) {
      vehicleStep.slots.rejectedVehicles = [];
    }
    
    rejectedVehicles.forEach(vehicle => {
      const exists = vehicleStep.slots.rejectedVehicles.some(v => 
        v.stock_number === vehicle.stock_number || 
        (v.make === vehicle.make && v.model === vehicle.model && v.year === vehicle.year)
      );
      
      if (!exists) {
        vehicleStep.slots.rejectedVehicles.push(this._slimVehicle(vehicle));
        console.log(`❌ Added ${vehicle.make} ${vehicle.model} to rejected vehicles`);
      }
    });
    
    console.log(`📊 Total rejected vehicles: ${vehicleStep.slots.rejectedVehicles.length}`);
  }

  handleVehicleSelection(conversationContext, selectedVehicle) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (!vehicleStep?.slots) return;
    
    if (!Array.isArray(vehicleStep.slots.selectedVehicles)) {
      vehicleStep.slots.selectedVehicles = [];
    }
    
    const exists = vehicleStep.slots.selectedVehicles.some(v => 
      v.stock_number === selectedVehicle.stock_number || 
      (v.make === selectedVehicle.make && v.model === selectedVehicle.model && v.year === selectedVehicle.year)
    );
    
    if (!exists) {
      vehicleStep.slots.selectedVehicles.push(this._slimVehicle(selectedVehicle));
      console.log(`✅ Added ${selectedVehicle.make} ${selectedVehicle.model} to selected vehicles`);
    }
    
    console.log(`📊 Total selected vehicles: ${vehicleStep.slots.selectedVehicles.length}`);
  }

  // Add vehicle to shared vehicles array
  addToSharedVehicles(conversationContext, vehicle) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (vehicleStep?.slots) {
      if (!Array.isArray(vehicleStep.slots.sharedVehicles)) {
        vehicleStep.slots.sharedVehicles = [];
      }
      
      // Check if vehicle already exists
      const exists = vehicleStep.slots.sharedVehicles.some(v => 
        v.stock_number === vehicle.stock_number || 
        (v.make === vehicle.make && v.model === vehicle.model && v.year === vehicle.year)
      );
      
      if (!exists) {
        vehicleStep.slots.sharedVehicles.push({
          stock_number: vehicle.stock_number || vehicle.id || 'N/A',
          make: vehicle.make,
          model: vehicle.model,
          year: vehicle.year,
          price: vehicle.price,
          color: vehicle.colors?.[0] || vehicle.color || 'N/A',
          shared_at: new Date().toISOString()
        });
      }
    }
  }

  // Add vehicle to selected vehicles array
  addToSelectedVehicles(conversationContext, vehicle) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (vehicleStep?.slots) {
      if (!Array.isArray(vehicleStep.slots.selectedVehicles)) {
        vehicleStep.slots.selectedVehicles = [];
      }
      
      // Check if vehicle already exists
      const exists = vehicleStep.slots.selectedVehicles.some(v => 
        v.stock_number === vehicle.stock_number || 
        (v.make === vehicle.make && v.model === vehicle.model && v.year === vehicle.year)
      );
      
      if (!exists) {
        vehicleStep.slots.selectedVehicles.push({
          stock_number: vehicle.stock_number || vehicle.id || 'N/A',
          make: vehicle.make,
          model: vehicle.model,
          year: vehicle.year,
          price: vehicle.price,
          color: vehicle.color,
          features: [], // ✅ Empty array to reduce memory usage
          selected_at: new Date().toISOString()
        });
      }
    }
  }

  // Sync arrays with conversation context slots
  syncWithSlots(conversationContext) {
    const vehicleStep = conversationContext.Daivesteps?.[3];
    if (vehicleStep?.slots) {
      // Initialize arrays if they don't exist
      if (!Array.isArray(vehicleStep.slots.sharedVehicles)) {
        vehicleStep.slots.sharedVehicles = [];
      }
      if (!Array.isArray(vehicleStep.slots.rejectedVehicles)) {
        vehicleStep.slots.rejectedVehicles = [];
      }
      if (!Array.isArray(vehicleStep.slots.selectedVehicles)) {
        vehicleStep.slots.selectedVehicles = [];
      }
      
      console.log('✅ Array tracking synced with Daivesteps structure');
    }
  }
}

// ✅ NEW: Comparison Strategy Implementation
class VehicleComparisonManager {
  constructor() {
    this.comparisonPatterns = [
      /compare|comparison|which.*better|difference|vs|versus/i,
      /can you compare|show me.*compare|compare.*these/i
    ];
  }

  // Detect if user wants vehicle comparison
  detectComparisonRequest(userMessage) {
    return this.comparisonPatterns.some(pattern => pattern.test(userMessage));
  }

  // Generate vehicle comparison
  compareVehicles(vehicleA, vehicleB, customerPreferences = {}) {
    const comparison = {
      vehicleA: this.formatVehicleForComparison(vehicleA),
      vehicleB: this.formatVehicleForComparison(vehicleB),
      comparison: {
        price: this.comparePrice(vehicleA, vehicleB),
        features: this.compareFeatures(vehicleA, vehicleB),
        fuel_efficiency: this.compareFuelEfficiency(vehicleA, vehicleB),
        safety: this.compareSafety(vehicleA, vehicleB),
        warranty: this.compareWarranty(vehicleA, vehicleB)
      },
      recommendation: this.generateRecommendation(vehicleA, vehicleB, customerPreferences)
    };

    return comparison;
  }

  // Format vehicle for comparison display
  formatVehicleForComparison(vehicle) {
    return {
      model: `${vehicle.make} ${vehicle.model}`,
      year: vehicle.year,
      price: vehicle.price,
      trim: vehicle.trim || 'Base',
      color: vehicle.color || 'N/A',
      features: vehicle.features || [],
      mileage: vehicle.mileage || 'New',
      stock_number: vehicle.stock_number || vehicle.id
    };
  }

  // Compare prices
  comparePrice(vehicleA, vehicleB) {
    const priceA = parseFloat(vehicleA.price) || 0;
    const priceB = parseFloat(vehicleB.price) || 0;
    const difference = Math.abs(priceA - priceB);
    
    return {
      vehicleA_price: priceA,
      vehicleB_price: priceB,
      difference: difference,
      cheaper: priceA < priceB ? 'A' : priceB < priceA ? 'B' : 'equal',
      savings: priceA < priceB ? difference : priceB < priceA ? difference : 0
    };
  }

  // Compare features
  compareFeatures(vehicleA, vehicleB) {
    const featuresA = vehicleA.features || [];
    const featuresB = vehicleB.features || [];
    
    const uniqueToA = featuresA.filter(f => !featuresB.includes(f));
    const uniqueToB = featuresB.filter(f => !featuresA.includes(f));
    const common = featuresA.filter(f => featuresB.includes(f));

    return {
      vehicleA_unique: uniqueToA,
      vehicleB_unique: uniqueToB,
      common_features: common,
      total_features: {
        A: featuresA.length,
        B: featuresB.length
      }
    };
  }

  // Compare fuel efficiency
  compareFuelEfficiency(vehicleA, vehicleB) {
    const mpgA = vehicleA.mpg || vehicleA.fuel_efficiency || 'N/A';
    const mpgB = vehicleB.mpg || vehicleB.fuel_efficiency || 'N/A';
    
    return {
      vehicleA_mpg: mpgA,
      vehicleB_mpg: mpgB,
      better_efficiency: this.getBetterEfficiency(mpgA, mpgB)
    };
  }

  // Compare safety features
  compareSafety(vehicleA, vehicleB) {
    const safetyA = this.extractSafetyFeatures(vehicleA);
    const safetyB = this.extractSafetyFeatures(vehicleB);
    
    return {
      vehicleA_safety: safetyA,
      vehicleB_safety: safetyB,
      safety_rating: this.compareSafetyRatings(vehicleA, vehicleB)
    };
  }

  // Compare warranty
  compareWarranty(vehicleA, vehicleB) {
    const warrantyA = vehicleA.warranty || 'Standard';
    const warrantyB = vehicleB.warranty || 'Standard';
    
    return {
      vehicleA_warranty: warrantyA,
      vehicleB_warranty: warrantyB,
      better_warranty: this.getBetterWarranty(warrantyA, warrantyB)
    };
  }

  // Generate recommendation based on customer preferences
  generateRecommendation(vehicleA, vehicleB, preferences) {
    let scoreA = 0;
    let scoreB = 0;
    
    // Price preference
    if (preferences.max_price) {
      const priceA = parseFloat(vehicleA.price) || 0;
      const priceB = parseFloat(vehicleB.price) || 0;
      
      if (priceA <= preferences.max_price) scoreA++;
      if (priceB <= preferences.max_price) scoreB++;
    }
    
    // Feature preferences
    if (preferences.preferred_features) {
      const featuresA = vehicleA.features || [];
      const featuresB = vehicleB.features || [];
      
      const matchingA = preferences.preferred_features.filter(f => featuresA.includes(f)).length;
      const matchingB = preferences.preferred_features.filter(f => featuresB.includes(f)).length;
      
      scoreA += matchingA;
      scoreB += matchingB;
    }
    
    // Make preference
    if (preferences.preferred_make) {
      if (preferences.preferred_make.includes(vehicleA.make)) scoreA++;
      if (preferences.preferred_make.includes(vehicleB.make)) scoreB++;
    }
    
    return {
      recommended: scoreA > scoreB ? 'A' : scoreB > scoreA ? 'B' : 'equal',
      reasoning: this.generateReasoning(vehicleA, vehicleB, preferences, scoreA, scoreB)
    };
  }

  // Generate reasoning for recommendation
  generateReasoning(vehicleA, vehicleB, preferences, scoreA, scoreB) {
    const reasons = [];
    
    if (scoreA > scoreB) {
      reasons.push(`${vehicleA.make} ${vehicleA.model} better matches your preferences`);
    } else if (scoreB > scoreA) {
      reasons.push(`${vehicleB.make} ${vehicleB.model} better matches your preferences`);
    } else {
      reasons.push('Both vehicles are equally good matches for your preferences');
    }
    
    return reasons.join('. ');
  }

  // Helper methods
  getBetterEfficiency(mpgA, mpgB) {
    const numA = parseFloat(mpgA);
    const numB = parseFloat(mpgB);
    
    if (isNaN(numA) || isNaN(numB)) return 'unknown';
    return numA > numB ? 'A' : numB > numA ? 'B' : 'equal';
  }

  extractSafetyFeatures(vehicle) {
    const safetyKeywords = ['airbag', 'abs', 'traction', 'stability', 'blind spot', 'lane departure', 'collision'];
    return (vehicle.features || []).filter(f => 
      safetyKeywords.some(keyword => f.toLowerCase().includes(keyword))
    );
  }

  compareSafetyRatings(vehicleA, vehicleB) {
    // This would typically use actual safety rating data
    return {
      vehicleA_rating: vehicleA.safety_rating || 'N/A',
      vehicleB_rating: vehicleB.safety_rating || 'N/A'
    };
  }

  getBetterWarranty(warrantyA, warrantyB) {
    // Simple comparison - in real implementation, parse warranty terms
    return warrantyA.length > warrantyB.length ? 'A' : warrantyB.length > warrantyA.length ? 'B' : 'equal';
  }
}

