DAIVEService.prototype.generateConversationalInventoryResponse = function(intentResult, inventoryData, userMessage) {
  const message = userMessage.toLowerCase();
  const vehicleType = intentResult.extracted_info?.vehicle_type || 'vehicle';
  const budget = intentResult.extracted_info?.budget_range;
  
  // Group vehicles by make for better presentation
  const vehiclesByMake = {};
  inventoryData.slice(0, 4).forEach(vehicle => {
    if (!vehiclesByMake[vehicle.make]) {
      vehiclesByMake[vehicle.make] = [];
    }
    vehiclesByMake[vehicle.make].push(vehicle);
  });
  
  let response = `Perfect! I found some great ${vehicleType} options for you:\n\n`;
  
  // Add vehicles in a conversational format
  Object.keys(vehiclesByMake).forEach(make => {
    const vehicles = vehiclesByMake[make];
    vehicles.forEach(vehicle => {
      const year = vehicle.year || 'N/A';
      const model = vehicle.model || 'N/A';
      const trim = vehicle.trim ? ` ${vehicle.trim}` : '';
      const price = vehicle.price ? `$${vehicle.price.toLocaleString()}` : 'Contact for pricing';
      const color = vehicle.color || 'Available colors';
      const mileage = vehicle.mileage ? `${vehicle.mileage.toLocaleString()} miles` : 'Low mileage';
      
      response += `${year} ${make} ${model}${trim} – ${price}, ${color}, ${mileage}\n`;
    });
  });
  
  if (budget) {
    response += `\n💡 All of these are within your ${budget} budget range.`;
  }
  
  response += `\n\n👉 Which one catches your eye? I can tell you more about any of them!`;
  
  return response;
};

DAIVEService.prototype.handleVehicleRejection = function(conversationContext, rejectedVehicles) {
  const vehicleStep = conversationContext.Daivesteps?.[3];
  if (!vehicleStep?.slots) return;
  
  if (!Array.isArray(vehicleStep.slots.rejectedVehicles)) {
    vehicleStep.slots.rejectedVehicles = [];
  }
  
  rejectedVehicles.forEach(vehicle => {
    const exists = vehicleStep.slots.rejectedVehicles.some(v => 
      v.stock_number === vehicle.stock_number || 
      (v.make === vehicle.make && v.model === vehicle.model && v.year === vehicle.year)
    );
    
    if (!exists) {
      vehicleStep.slots.rejectedVehicles.push(this._slimVehicle(vehicle));
      console.log(`❌ Added ${vehicle.make} ${vehicle.model} to rejected vehicles`);
    }
  });
  
  console.log(`📊 Total rejected vehicles: ${vehicleStep.slots.rejectedVehicles.length}`);
};

