/**
 * ✅ NEW: Enhanced budget update logic with renegotiation support
 */
DAIVEService.prototype.updateBudgetWithRenegotiationCheck = function(conversationContext, userMessage, budgetData) {
  try {
    // First check if this is a budget renegotiation request
    const isRenegotiation = this.handleBudgetRenegotiation(conversationContext, userMessage, budgetData);
    
    if (isRenegotiation) {
      console.log('💰 Budget renegotiation handled successfully');
      return true;
    }
    
    // If not renegotiation, proceed with normal budget update
    const leadCaptureStepKey = '2';
    
    if (budgetData?.target_price) {
      this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'budget.target_price', budgetData.target_price);
      this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
    }
    
    if (budgetData?.max_price) {
      this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'budget.max_price', budgetData.max_price);
      this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
    }
    
    if (budgetData?.has_budget) {
      this.updateDaivestepsField(conversationContext, leadCaptureStepKey, 'budget.has_budget', budgetData.has_budget);
      this.checkAndUpdateStepCompletion(conversationContext, leadCaptureStepKey);
    }
    
    return true;
  } catch (error) {
    console.error('❌ Error updating budget with renegotiation check:', error);
    return false;
  }
};

/**
 * ✅ NEW: Check if budget update should be allowed in current progression step
 */
DAIVEService.prototype.shouldAllowBudgetUpdate = function(conversationContext, userMessage) {
  try {
    const currentStep = conversationContext.currentJourneyStep;
    
    // Always allow budget updates in lead capture step
    if (currentStep === 'lead_capture') {
      return true;
    }
    
    // For other steps, only allow if it's a budget renegotiation request
    if (this.isBudgetExtensionRequested(userMessage, conversationContext)) {
      console.log('💰 Budget renegotiation request detected in progression step');
      return true;
    }
    
    // Check if we're in a step where budget changes are not appropriate
    const budgetRestrictedSteps = [
      'vehicle_selection', 'test_drive', 'trade_evaluation', 
      'qualification', 'purchase_commitment', 'vehicle_prep',
      'finance_manager', 'delivery', 'csi_followup'
    ];
    
    if (budgetRestrictedSteps.includes(currentStep)) {
      console.log(`⚠️ Budget update not allowed in ${currentStep} step unless renegotiation requested`);
      return false;
    }
    
    return true;
  } catch (error) {
    console.error('❌ Error checking budget update permission:', error);
    return false;
  }
};

/**
 * ✅ NEW: Enhanced budget update with progression step validation
 */
DAIVEService.prototype.updateBudgetWithProgressionCheck = function(conversationContext, userMessage, budgetData) {
  try {
    // Check if budget update is allowed in current progression step
    if (!this.shouldAllowBudgetUpdate(conversationContext, userMessage)) {
      console.log('🚫 Budget update blocked - not allowed in current progression step');
      return false;
    }
    
    // Use the enhanced budget update logic
    return this.updateBudgetWithRenegotiationCheck(conversationContext, userMessage, budgetData);
  } catch (error) {
    console.error('❌ Error updating budget with progression check:', error);
    return false;
  }
};

/**
 * ✅ NEW: Get budget renegotiation status for lead capture step
 */
DAIVEService.prototype.getBudgetRenegotiationStatus = function(conversationContext) {
  try {
    const leadCaptureStepKey = 'Step 2 - Lead Capture';
    const stepData = conversationContext.Daivesteps?.[leadCaptureStepKey];
    
    if (!stepData) {
      return {
        hasBudget: false,
        isRenegotiated: false,
        renegotiatedAt: null,
        currentBudget: null
      };
    }
    
    return {
      hasBudget: stepData.budget?.has_budget || stepData.slots?.budget?.has_budget || false,
      isRenegotiated: stepData.budget?.renegotiated || stepData.slots?.budget?.renegotiated || false,
      renegotiatedAt: stepData.budget?.renegotiated_at || stepData.slots?.budget?.renegotiated_at || null,
      currentBudget: {
        target_price: stepData.budget?.target_price || stepData.slots?.budget?.target_price || null,
        max_price: stepData.budget?.max_price || stepData.slots?.budget?.max_price || null
      }
    };
  } catch (error) {
    console.error('❌ Error getting budget renegotiation status:', error);
    return null;
  }
};



