  /**
   * Extract basic information from user message
   */
  extractBasicInfo(userMessage) {
    const message = userMessage.toLowerCase();
    const extractedInfo = {};
    
    // Extract vehicle type
    if (message.includes('suv') || message.includes('sport utility')) {
      extractedInfo.vehicle_type = 'SUV';
    } else if (message.includes('truck') || message.includes('pickup')) {
      extractedInfo.vehicle_type = 'truck';
    } else if (message.includes('car') || message.includes('sedan')) {
      extractedInfo.vehicle_type = 'car';
    } else if (message.includes('hybrid') || message.includes('electric')) {
      extractedInfo.vehicle_type = 'hybrid';
    }
    
    // Extract budget information (but not vehicle selections)
    const isVehicleSelection = message.includes('option') || message.includes('choice') || message.includes('select');
    if (!isVehicleSelection) {
      const budgetMatch = message.match(/\$?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)\s*(?:k|thousand|grand)?/i);
      if (budgetMatch) {
        let amount = parseFloat(budgetMatch[1].replace(/,/g, ''));
        if (message.includes('k') || message.includes('thousand') || message.includes('grand')) {
          amount *= 1000;
        }
        // Only extract as budget if it's a reasonable amount
        if (amount >= 1000 && amount <= 200000) {
          extractedInfo.budget_range = amount;
        }
      }
    }
    
    return extractedInfo;
  }

