  /**
   * Get cached intent result
   */
  getCachedIntent(userMessage, conversationContext = {}) {
    try {
      if (!this.intentCache) {
        this.intentCache = new Map();
      }
      // Include journey step so the same phrase at different stages doesn't
      // return a stale cached intent (e.g. "yes" means different things at
      // step 2 vs step 5).
      const journeyStep = conversationContext.currentJourneyStep || 'inquiry';
      const cacheKey = this.generateCacheKey(userMessage) + ':' + journeyStep;
      const cached = this.intentCache.get(cacheKey);
      if (cached) {
        console.log('⚡ Intent cache hit for:', cacheKey);
      }
      return cached || null;
    } catch (error) {
      console.log('⚠️ Cache retrieval error:', error.message);
      return null;
    }
  }

  /**
   * Cache intent result
   */
  cacheIntent(userMessage, intentResult, conversationContext = {}) {
    try {
      if (!this.intentCache) {
        this.intentCache = new Map();
      }
      const journeyStep = conversationContext.currentJourneyStep || 'inquiry';
      const cacheKey = this.generateCacheKey(userMessage) + ':' + journeyStep;
      this.intentCache.set(cacheKey, intentResult);

      // Limit cache size
      if (this.intentCache.size > 100) {
        const firstKey = this.intentCache.keys().next().value;
        this.intentCache.delete(firstKey);
      }
    } catch (error) {
      console.log('⚠️ Cache storage error:', error.message);
    }
  }
  
  /**
   * Generate cache key for intent detection
   */
  generateCacheKey(userMessage, conversationContext = null) {
    if (conversationContext) {
      // ✅ SIMPLIFIED: Use conversationContext directly instead of getUnifiedSlots
      const slots = conversationContext.Daivesteps || {};
      const dealerId = conversationContext?.dealerId || this.dealerId || 'default';
      const key = `${userMessage.toLowerCase()}_${JSON.stringify(slots)}_${dealerId}`;
      return key.substring(0, 100); // Limit key length
    }
    return userMessage.toLowerCase().trim().substring(0, 50);
  }
  
  /**
   * Get default intent when all detection fails
   */
  getDefaultIntent() {
    return {
      intent: 'general_inquiry',
      confidence: 0.5,
      extracted_info: {},
      method: 'default_fallback'
    };
  }


  /**
   * ✅ NEW: Detect and respond to simple greetings with fast rule-based responses
   * Only matches very basic greetings - anything complex goes to LLM
   */
  detectSimpleGreeting(userMessage) {
    const msg = userMessage.toLowerCase().trim();
    
    // Remove common punctuation for matching
    const cleaned = msg.replace(/[?.!,]/g, '').trim();
    
    // ✅ EXACT MATCH: Simple greetings only
    const simpleGreetings = {
      // Basic hellos
      'hi': { type: 'hello', response: "Hello! How can I help you today?" },
      'hello': { type: 'hello', response: "Hello! How can I help you today?" },
      'hey': { type: 'hello', response: "Hey there! What brings you in today?" },
      'hi there': { type: 'hello', response: "Hi! How can I assist you?" },
      'hello there': { type: 'hello', response: "Hello! What can I do for you today?" },
      
      // How are you variations
      'how are you': { type: 'how_are_you', response: "I'm doing great, thank you! How can I help you today?" },
      'how are you doing': { type: 'how_are_you', response: "I'm doing well, thanks for asking! What brings you in?" },
      'how you doing': { type: 'how_are_you', response: "I'm doing great! How about you? What can I help you with?" },
      'how are you today': { type: 'how_are_you', response: "I'm doing wonderful today! How can I assist you?" },
      'how you doing today': { type: 'how_are_you', response: "I'm doing great today! What brings you in?" },
      'hows it going': { type: 'how_are_you', response: "It's going well! How can I help you today?" },
      'how is it going': { type: 'how_are_you', response: "It's going great! What can I do for you?" },
      'whats up': { type: 'how_are_you', response: "Not much! How can I help you today?" },
      'sup': { type: 'how_are_you', response: "Hey! What can I help you with?" },
      
      // Good morning/afternoon/evening
      'good morning': { type: 'time_greeting', response: "Good morning! How can I help you today?" },
      'good afternoon': { type: 'time_greeting', response: "Good afternoon! What brings you in?" },
      'good evening': { type: 'time_greeting', response: "Good evening! How can I assist you?" },
      
      // Thanks variations (short)
      'thanks': { type: 'thanks', response: "You're welcome! Is there anything else I can help with?" },
      'thank you': { type: 'thanks', response: "You're very welcome! Let me know if you need anything else." },
      'ty': { type: 'thanks', response: "You're welcome! Happy to help!" },
      'thx': { type: 'thanks', response: "You're welcome!" },
      
      // Goodbyes (short)
      'bye': { type: 'goodbye', response: "Goodbye! Feel free to reach out anytime!" },
      'goodbye': { type: 'goodbye', response: "Goodbye! Have a great day!" },
      'see you': { type: 'goodbye', response: "See you! Take care!" },
      'later': { type: 'goodbye', response: "See you later! Have a great day!" },
    };
    
    // Check for exact match
    if (simpleGreetings[cleaned]) {
      return simpleGreetings[cleaned];
    }
    
    // ✅ PATTERN MATCH: Only very simple patterns
    // If message is longer than 8 words, use LLM
    const wordCount = cleaned.split(/\s+/).length;
    if (wordCount > 8) {
      return null; // Too complex, use LLM
    }
    
    // Pattern: "hi/hello/hey" + optional name
    if (/^(hi|hello|hey)(\s+\w+)?$/.test(cleaned)) {
      return { type: 'hello', response: "Hello! How can I help you today?" };
    }
    
    // Pattern: "good" + time of day
    if (/^good\s+(morning|afternoon|evening|night)(\s+\w+)?$/.test(cleaned)) {
      return { type: 'time_greeting', response: "Good to see you! How can I assist you today?" };
    }
    
    // If no match, return null to use LLM
    return null;
  }

  /**
   * ✅ NEW: Get next stage in journey
   */
  getNextStage(currentStep) {
    const stageProgression = {
      'inquiry': 'lead_capture',
      'lead_capture': 'vehicle_selection',
      'vehicle_selection': 'test_drive',
      'test_drive': 'trade_evaluation',
      'trade_evaluation': 'qualification',
      'qualification': 'purchase_commitment',
      'purchase_commitment': 'completed'
    };
    return stageProgression[currentStep] || 'inquiry';
  }

  /**
   * ✅ NEW: Get stage-friendly display name
   */
  getStageDisplayName(stage) {
    const displayNames = {
      'inquiry': 'Initial Inquiry',
      'lead_capture': 'Budget Discussion',
      'vehicle_selection': 'Vehicle Selection',
      'test_drive': 'Test Drive',
      'trade_evaluation': 'Trade-In Evaluation',
      'qualification': 'Financing & Qualification',
      'purchase_commitment': 'Purchase Commitment',
      'completed': 'Purchase Complete'
    };
    return displayNames[stage] || stage;
  }



