  /**
   * ✅ NEW: Get daivestep progress for context
   */
  getDaivestepProgress(conversationContext) {
    const daivesteps = conversationContext.Daivesteps || {};
    const stepCompleted = conversationContext.stepCompleted || {};
    
    return {
      currentStep: conversationContext.currentJourneyStep || 'inquiry',
      stepCompleted: stepCompleted,
      daivesteps: daivesteps,
      lastUpdated: conversationContext.last_updated || new Date().toISOString()
    };
  }

  /**
   * ✅ NEW: Get next mandatory slots using existing system
   */
  getNextMandatorySlots(conversationContext) {
    if (this.optimizedCrewAI && this.optimizedCrewAI.journeyManager) {
      const journeyManager = this.optimizedCrewAI.journeyManager;
      const currentStep = conversationContext.currentJourneyStep;
      
      if (currentStep && journeyManager.mandatorySlots[currentStep]) {
        const mandatorySlots = journeyManager.mandatorySlots[currentStep];
        const missingSlots = mandatorySlots.filter(slot => 
          !journeyManager.hasSlotValue(conversationContext, slot)
        );
        return missingSlots;
      }
    }
    
    return [];
  }


