  getVehiclePrice(conversationContext) {
    console.log('🔍 Getting vehicle price from conversation context...');
    const normalizePrice = (value) => {
      if (typeof value === 'number') {
        return Number.isFinite(value) ? value : null;
      }
      if (typeof value === 'string') {
        const parsed = parseFloat(value.replace(/[$,\s]/g, ''));
        return Number.isFinite(parsed) ? parsed : null;
      }
      return null;
    };
    
    // ✅ PRIORITY 1: Get the most recent selected vehicle with correct price
    const selectedVehicle = this.getSelectedVehicle(conversationContext);
    
    const selectedVehiclePrice = normalizePrice(selectedVehicle?.price);
    if (selectedVehiclePrice && selectedVehiclePrice > 0) {
      console.log(`✅ Found vehicle price from MOST RECENT selected vehicle: $${selectedVehiclePrice}`);
      return selectedVehiclePrice;
    }
    
    // ✅ PRIORITY 2: Try to get the CORRECT price from vehicleDetails
    const vehicleDetails = conversationContext.vehicleDetails || [];
    
    if (selectedVehicle && vehicleDetails.length > 0) {
      // Find matching vehicle in vehicleDetails by stock number first
      const matchingVehicle = vehicleDetails.find(v => 
        v.stockNumber && selectedVehicle.stockNumber && 
        v.stockNumber.toLowerCase() === selectedVehicle.stockNumber.toLowerCase()
      );
      
      if (matchingVehicle && matchingVehicle.price) {
        // Extract numeric price from string format like "$18,410"
        const priceStr = matchingVehicle.price.replace(/[$,]/g, '');
        const correctPrice = parseFloat(priceStr);
        console.log(`✅ Found CORRECT vehicle price from vehicleDetails by stock number: $${correctPrice}`);
        return correctPrice;
      }
      
      // Fallback: Find matching vehicle in vehicleDetails by year/make/model
      const fallbackMatch = vehicleDetails.find(v => 
        v.year === selectedVehicle.year && 
        v.make?.toLowerCase() === selectedVehicle.make?.toLowerCase() &&
        v.model?.toLowerCase() === selectedVehicle.model?.toLowerCase()
      );
      
      if (fallbackMatch && fallbackMatch.price) {
        // Extract numeric price from string format like "$18,410"
        const priceStr = fallbackMatch.price.replace(/[$,]/g, '');
        const correctPrice = parseFloat(priceStr);
        console.log(`✅ Found CORRECT vehicle price from vehicleDetails by vehicle match: $${correctPrice}`);
        return correctPrice;
      }
    }
    
    // Method 2: Try to get from VehicleSelection in step 3
    const vehicleData = conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection?.[0];
    const vehicleDataPrice = normalizePrice(vehicleData?.price);
    if (vehicleDataPrice) {
      console.log(`✅ Found vehicle price from VehicleSelection: $${vehicleDataPrice}`);
      return vehicleDataPrice;
    }
    
    // Method 3: Try to get from selectedVehicles array
    const selectedVehicles = conversationContext.Daivesteps?.[3]?.slots?.selectedVehicles || [];
    if (selectedVehicles.length > 0) {
      const selectedVehicle = selectedVehicles[0];
      console.log(`🔍 Checking selectedVehicles[0]:`, selectedVehicle);
      
      // If price is 0 or null, try to find the actual price from vehicleDetails
      const selectedVehicleListPrice = normalizePrice(selectedVehicle.price);
      if (!selectedVehicleListPrice) {
        console.log(`⚠️ Selected vehicle price is ${selectedVehicle.price}, looking in vehicleDetails...`);
        
        // Get vehicleDetails from conversationContext
        const vehicleDetails = conversationContext.vehicleDetails || conversationContext.conversationContext?.vehicleDetails || [];
        console.log(`🔍 Available vehicleDetails:`, vehicleDetails.length, 'vehicles');
        console.log(`🔍 vehicleDetails source:`, {
          direct: conversationContext.vehicleDetails?.length || 0,
          nested: conversationContext.conversationContext?.vehicleDetails?.length || 0,
          total: vehicleDetails.length
        });
        
        // Find matching vehicle by stock number
        const matchingVehicle = vehicleDetails.find(v => 
          v.stockNumber && selectedVehicle.stockNumber && 
          v.stockNumber.toLowerCase() === selectedVehicle.stockNumber.toLowerCase()
        );
        
        if (matchingVehicle && matchingVehicle.price) {
          const priceValue = parseFloat(matchingVehicle.price.replace(/[$,]/g, ''));
          console.log(`✅ Found actual price from vehicleDetails for ${selectedVehicle.stockNumber}: $${priceValue}`);
          return priceValue;
        }
        
        // Fallback: try to match by year, make, model if stock number doesn't match
        const fallbackMatch = vehicleDetails.find(v => 
          v.year === selectedVehicle.year &&
          v.make && selectedVehicle.make &&
          v.make.toLowerCase() === selectedVehicle.make.toLowerCase() &&
          v.model && selectedVehicle.model &&
          v.model.toLowerCase() === selectedVehicle.model.toLowerCase()
        );
        
        if (fallbackMatch && fallbackMatch.price) {
          const priceValue = parseFloat(fallbackMatch.price.replace(/[$,]/g, ''));
          console.log(`✅ Found price by vehicle match (${selectedVehicle.year} ${selectedVehicle.make} ${selectedVehicle.model}): $${priceValue}`);
          return priceValue;
        }
      } else {
        console.log(`✅ Found vehicle price from selectedVehicles: $${selectedVehicleListPrice}`);
        return selectedVehicleListPrice;
      }
    }
    
    // Method 4: Try to extract price from vehicle details if stored as string
    const stepVehicleDetails = conversationContext.Daivesteps?.[3]?.slots?.vehicleDetails;
    const stepVehicleDetailsPrice = normalizePrice(stepVehicleDetails?.price);
    if (stepVehicleDetailsPrice) {
      console.log(`✅ Found vehicle price from vehicleDetails: $${stepVehicleDetailsPrice}`);
      return stepVehicleDetailsPrice;
    }
    
    // Method 5: Try to get from conversationContext.vehicleDetails array (NEW)
    const conversationVehicleDetails = conversationContext.conversationContext?.vehicleDetails;
    if (conversationVehicleDetails && Array.isArray(conversationVehicleDetails)) {
      // Find the selected vehicle by stock number
      const selectedStockNumber = conversationContext.conversationContext?.vehicleSelectionNumber;
      if (selectedStockNumber) {
        const selectedVehicleDetail = conversationVehicleDetails.find(v => 
          v.stockNumber && v.stockNumber.toLowerCase() === selectedStockNumber.toLowerCase()
        );
        if (selectedVehicleDetail && selectedVehicleDetail.price) {
          // Extract numeric value from price string like "$21,185"
          const priceValue = parseFloat(selectedVehicleDetail.price.replace(/[$,]/g, ''));
          console.log(`✅ Found vehicle price from conversationContext.vehicleDetails: $${priceValue}`);
          return priceValue;
        }
      }
      
      // Fallback: get the first vehicle with a price
      const vehicleWithPrice = conversationVehicleDetails.find(v => v.price);
      if (vehicleWithPrice && vehicleWithPrice.price) {
        const priceValue = parseFloat(vehicleWithPrice.price.replace(/[$,]/g, ''));
        console.log(`✅ Found vehicle price from conversationContext.vehicleDetails (fallback): $${priceValue}`);
        return priceValue;
      }
    }
    
    console.log('❌ No vehicle price found in conversation context');
    return null; // Return null instead of 0 to indicate no price found
  }

