  calculateMonthlyPayment(principal, annualRate, months) {
    // Convert annual rate to monthly rate
    const monthlyRate = annualRate / 100 / 12;
    
    // Calculate monthly payment using the loan formula
    if (monthlyRate === 0) {
      // Handle 0% interest case
      return principal / months;
    }
    
    const monthlyPayment = principal * (monthlyRate * Math.pow(1 + monthlyRate, months)) / 
                          (Math.pow(1 + monthlyRate, months) - 1);
    
    return monthlyPayment;
  }

  generateLeaseOptions(vehiclePrice = 35000, tradeInValue = 0, leaseTerm = 36) {
    const netPrice = vehiclePrice - tradeInValue;
    const residualValue = this.calculateResidualValue(vehiclePrice, leaseTerm);
    const leaseAmount = netPrice - residualValue;
    
    let options = [];
    
    if (leaseTerm === 24) {
      const monthly24 = this.calculateLeasePayment(leaseAmount, 2.9, 24);
      options.push(`• **24-Month Lease**: 2.9% APR - **$${monthly24.toFixed(0)}/month** (Residual: $${residualValue.toFixed(0)})`);
    } else if (leaseTerm === 36) {
      const monthly36 = this.calculateLeasePayment(leaseAmount, 3.9, 36);
      options.push(`• **36-Month Lease**: 3.9% APR - **$${monthly36.toFixed(0)}/month** (Residual: $${residualValue.toFixed(0)})`);
    } else if (leaseTerm === 48) {
      const monthly48 = this.calculateLeasePayment(leaseAmount, 4.9, 48);
      options.push(`• **48-Month Lease**: 4.9% APR - **$${monthly48.toFixed(0)}/month** (Residual: $${residualValue.toFixed(0)})`);
    }
    
    return options.join('\n');
  }

  calculateResidualValue(vehiclePrice, leaseTerm) {
    // Calculate residual value based on lease term
    if (leaseTerm === 24) {
      return vehiclePrice * 0.75; // 75% residual for 24 months
    } else if (leaseTerm === 36) {
      return vehiclePrice * 0.65; // 65% residual for 36 months
    } else if (leaseTerm === 48) {
      return vehiclePrice * 0.55; // 55% residual for 48 months
    }
    return vehiclePrice * 0.65; // Default 36-month residual
  }

  calculateLeasePayment(leaseAmount, annualRate, months) {
    // Convert annual rate to monthly rate
    const monthlyRate = annualRate / 100 / 12;
    
    // Calculate lease payment
    if (monthlyRate === 0) {
      return leaseAmount / months;
    }
    
    const monthlyPayment = leaseAmount * (monthlyRate * Math.pow(1 + monthlyRate, months)) / 
                          (Math.pow(1 + monthlyRate, months) - 1);
    
    return monthlyPayment;
  }

 

  async handlePurchaseCommitmentStep(userMessage, intentResult, conversationContext, slots) {
    console.log('✅ Handling Purchase Commitment Step');
    
    // Check if we're collecting final purchase details
    const purchaseStep = conversationContext.Daivesteps?.[7]?.slots?.purchaseCommitment || {};
    
    // Detect purchase commitment from user message
    const purchaseDetails = this.extractPurchaseCommitmentDetails(userMessage);
    
    if (purchaseDetails) {
      // Store purchase details
      if (!conversationContext.Daivesteps[7]) {
        conversationContext.Daivesteps[7] = { slots: {} };
      }
      conversationContext.Daivesteps[7].slots.purchaseCommitment = {
        ...purchaseStep,
        ...purchaseDetails,
        collectedAt: new Date().toISOString()
      };
      
      // Check if we have enough details for finalization
      const hasEnoughDetails = this.hasEnoughPurchaseDetails(conversationContext.Daivesteps[7].slots.purchaseCommitment);
      
      if (hasEnoughDetails) {
        // Finalize the deal
        const dealSummary = this.generateDealSummary(conversationContext);
        
        // Mark purchase commitment as completed
        conversationContext.Daivesteps[7].status = 'completed';
        conversationContext.Daivesteps[7].completedAt = new Date().toISOString();
        
        // Mark entire journey as completed
        conversationContext.journeyCompleted = true;
        conversationContext.journeyCompletedAt = new Date().toISOString();
        
        return {
          response: `🎉 **Congratulations! Your deal is finalized!**\n\n${dealSummary}\n\nWe'll have everything ready for pickup/delivery. Thank you for choosing Clay Cooley Hyundai!`,
          agentType: 'Sales Manager',
          conversationContext
        };
      } else {
        // Ask for missing details
        const missingDetail = this.getMissingPurchaseDetail(conversationContext.Daivesteps[7].slots.purchaseCommitment);
        return {
          response: `Perfect! To finalize your purchase, I need to know: ${missingDetail}`,
          agentType: 'Sales Manager',
          conversationContext
        };
      }
    }
    
    // Initial purchase commitment inquiry
    return {
      response: "Excellent! Are you ready to finalize your purchase? I'll need to know your preferred delivery method (pickup or delivery) and any additional services you'd like.",
      agentType: 'Sales Manager',
      conversationContext
    };
  }

  // Helper methods for purchase commitment
  extractPurchaseCommitmentDetails(userMessage) {
    const message = userMessage.toLowerCase();
    const details = {};
    
    // Extract delivery method
    if (message.includes('pickup') || message.includes('pick up')) details.deliveryMethod = 'pickup';
    else if (message.includes('delivery') || message.includes('deliver')) details.deliveryMethod = 'delivery';
    
    // Extract additional services
    if (message.includes('warranty') || message.includes('extended warranty')) details.warranty = true;
    if (message.includes('insurance') || message.includes('gap insurance')) details.insurance = true;
    if (message.includes('maintenance') || message.includes('service plan')) details.maintenance = true;
    
    // Extract commitment confirmation
    if (message.includes('yes') || message.includes('ready') || message.includes('finalize') || message.includes('commit')) {
      details.committed = true;
    }
    
    return Object.keys(details).length > 0 ? details : null;
  }
  
  hasEnoughPurchaseDetails(purchaseDetails) {
    return !!(purchaseDetails.committed && purchaseDetails.deliveryMethod);
  }
  
  getMissingPurchaseDetail(purchaseDetails) {
    if (!purchaseDetails.deliveryMethod) return "Would you prefer to pickup the vehicle or have it delivered?";
    if (!purchaseDetails.committed) return "Are you ready to commit to this purchase?";
    return null;
  }
  
  generateDealSummary(conversationContext) {
    const vehicleData = conversationContext.Daivesteps?.[3]?.slots?.inventoryData?.[0];
    const tradeData = conversationContext.Daivesteps?.[5]?.slots?.tradeEvaluation;
    const financeData = conversationContext.Daivesteps?.[6]?.slots?.qualification;
    const purchaseData = conversationContext.Daivesteps?.[7]?.slots?.purchaseCommitment;
    
    let summary = [];
    
    if (vehicleData) {
      summary.push(`**Vehicle**: ${vehicleData.year} ${vehicleData.make} ${vehicleData.model} - $${vehicleData.price?.toLocaleString()}`);
    }
    
    if (tradeData) {
      const tradeValue = this.generateTradeInValuation(tradeData);
      summary.push(`**Trade-in**: ${tradeData.year} ${tradeData.make} ${tradeData.model} - ${tradeValue}`);
    }
    
    if (financeData) {
      summary.push(`**Financing**: ${financeData.creditScore} credit profile`);
    }
    
    if (purchaseData) {
      summary.push(`**Delivery**: ${purchaseData.deliveryMethod}`);
      if (purchaseData.warranty) summary.push(`**Services**: Extended warranty included`);
      if (purchaseData.insurance) summary.push(`**Services**: Gap insurance included`);
      if (purchaseData.maintenance) summary.push(`**Services**: Maintenance plan included`);
    }
    
    return summary.join('\n');
  }

