  /**
   * FALLBACK RESPONSE: Generate response when LLM is not available
   */
  async generateFallbackResponse(intentResult, inventoryData, userMessage, conversationContext) {
    console.log('🔄 Generating fallback response (LLM not available)');
    
    // ✅ FIXED: Check mandatory slots before using fallback responses
    const mandatorySlotsFilled = this.slotManager ? this.slotManager.areMandatorySlotsFilled() : false;
    console.log('🔍 Fallback: Mandatory slots filled:', mandatorySlotsFilled);
    
    // ✅ CRITICAL: Auto-advance to vehicle_selection if mandatory slots are filled and in lead_capture
    if (mandatorySlotsFilled && conversationContext?.currentJourneyStep === 'lead_capture') {
      console.log('🚀 Fallback: Auto-advancing from lead_capture to vehicle_selection');
      conversationContext.currentJourneyStep = 'vehicle_selection';
      conversationContext.Currentstep = 'Vehicle Selection';
    }
    
    // If mandatory slots are filled and this is an inventory inquiry, search and show inventory
    if (intentResult.intent === 'inventory_inquiry' && mandatorySlotsFilled) {
      console.log('✅ Fallback: Mandatory slots filled, searching for inventory...');
      
      // ✅ CRITICAL: Search for inventory if not already available
      if (!inventoryData || inventoryData.length === 0) {
        console.log('🔍 No inventory data found, performing search...');
        
        // Get search criteria from mandatory slots
        const budget = this.slotManager?.getBudget();
        const vehicleType = this.slotManager?.getVehicleType();
        
        if (budget && vehicleType && this.inventoryService) {
          // Extract features from slots (optional)
          const step3Data = conversationContext.Daivesteps?.[3] || {};
          const features = step3Data.slots?.features || 
                           step3Data.slots?.VehicleSelection?.features || 
                           null;
          
          const searchCriteria = {
            vehicleType: vehicleType,
            max_price: budget.max_price || budget.target_price,
            target_price: budget.target_price || budget.max_price,
            ...(features && Array.isArray(features) && features.length > 0 ? { features } : {})
          };
          
          console.log('🔍 Searching with criteria:', searchCriteria);
          
          try {
            // Perform inventory search
            const searchResults = await this.inventoryService.searchVehiclesComprehensive(
              searchCriteria, 
              conversationContext.dealerId
            );
            
            if (searchResults && searchResults.length > 0) {
              console.log(`✅ Found ${searchResults.length} vehicles in inventory search`);
              
              // Store inventory data in conversation context
              if (!conversationContext.Daivesteps[3]) {
                conversationContext.Daivesteps[3] = { slots: {} };
              }
              conversationContext.Daivesteps[3].slots.inventoryData = searchResults;
              
              // Update inventory data for response
              inventoryData = searchResults;
            } else {
              console.log('❌ No vehicles found in inventory search');
            }
          } catch (error) {
            console.error('❌ Error searching inventory:', error);
          }
        }
      }
      
      // Show inventory if available
      if (inventoryData && inventoryData.length > 0) {
        console.log('✅ Fallback: Showing inventory with', inventoryData.length, 'vehicles');
        const vehicleCount = inventoryData.length;
        const budget = this.slotManager?.getBudget();
        const vehicleType = this.slotManager?.getVehicleType();
        
        let response = `Perfect! I have ${vehicleCount} ${vehicleType} options available within your budget. `;
        
        if (vehicleCount <= 3) {
          response += `Here are your options:\n\n`;
          inventoryData.slice(0, 3).forEach((vehicle, index) => {
            response += `${index + 1}. ${vehicle.year} ${vehicle.make} ${vehicle.model} - $${vehicle.price?.toLocaleString() || 'Price TBD'}\n`;
          });
        } else {
          response += `I can show you the top 3 options that best match your preferences. Would you like to see them?`;
        }
        
        return response;
      } else {
        console.log('❌ No inventory available after search');
        return `I don't have any ${this.slotManager?.getVehicleType() || 'vehicles'} available within your budget of $${(this.slotManager?.getBudget()?.max_price || this.slotManager?.getBudget()?.target_price || 0).toLocaleString()}. Would you like to expand your budget range or consider other vehicle types?`;
      }
    }
    
    // Intent-based fallback responses (only when mandatory slots are not filled)
    const fallbackResponses = {
      'buy_car': 'I can help you find the perfect vehicle! What make and model are you interested in?',
      'inventory_inquiry': mandatorySlotsFilled ? 
        'I have vehicles available that match your preferences. Would you like to see them?' : 
        'I have a great selection of vehicles available. What type of vehicle are you looking for?',
      'budget_inquiry': 'I can work with various budgets. What price range are you considering?',
      'test_drive': 'I\'d be happy to arrange a test drive! Which vehicle would you like to test?',
      'financing_options': 'I can help you explore financing options. What\'s your preferred payment method?',
      'vehicle_search': 'Let me help you find the right vehicle. What are your key requirements?',
      'general_inquiry': 'I\'m here to help with your vehicle needs. What can I assist you with today?'
    };
    
    const intent = intentResult.intent || 'general_inquiry';
    const baseResponse = fallbackResponses[intent] || fallbackResponses['general_inquiry'];
    
    // Add inventory context if available
    if (inventoryData && inventoryData.length > 0) {
      return `${baseResponse} I have ${inventoryData.length} vehicles that might interest you.`;
    }
    
    return baseResponse;
  }

