  /**
   * ✅ NEW: Apply optimized array solution for enhanced data structure
   * Transforms extracted fields into optimized format for better processing
   */
  applyOptimizedArraySolution(fields, currentStep) {
    try {
      const optimized = { ...fields };
      
      // Convert arrays to optimized format
      if (fields.features && Array.isArray(fields.features)) {
        optimized.features = {
          list: fields.features,
          count: fields.features.length,
          hasLeather: fields.features.some(f => f.toLowerCase().includes('leather')),
          hasSunroof: fields.features.some(f => f.toLowerCase().includes('sunroof')),
          hasNavigation: fields.features.some(f => f.toLowerCase().includes('navigation')),
          hasAWD: fields.features.some(f => f.toLowerCase().includes('awd') || f.toLowerCase().includes('4wd'))
        };
      }
      
      // Optimize budget information
      if (fields.budget || fields.target_price) {
        const budget = fields.budget || fields.target_price;
        optimized.budget = {
          amount: budget,
          range: `${budget - 5000}-${budget + 5000}`,
          category: budget < 25000 ? 'budget' : budget < 40000 ? 'mid-range' : 'luxury',
          formatted: `$${budget.toLocaleString()}`
        };
      }
      
      // Optimize vehicle information
      if (fields.make || fields.model) {
        optimized.vehicle = {
          make: fields.make,
          model: fields.model,
          fullName: `${fields.make} ${fields.model}`,
          type: fields.vehicle_type || fields.type,
          condition: fields.vehicle_condition || fields.condition
        };
      }
      
      // Optimize contact information
      if (fields.contact_phone || fields.contact_email) {
        optimized.contact = {
          phone: fields.contact_phone,
          email: fields.contact_email,
          hasPhone: !!fields.contact_phone,
          hasEmail: !!fields.contact_email,
          preferred: fields.contact_phone ? 'phone' : 'email'
        };
      }
      
      // Add step-specific optimizations
      optimized.step = currentStep;
      optimized.stepNumber = this.getStepNumber(currentStep);
      optimized.stepDisplayName = this.getStepDisplayName(currentStep);
      optimized.extractionTimestamp = new Date().toISOString();
      
      console.log('✅ Optimized array solution applied:', {
        originalFields: Object.keys(fields).length,
        optimizedFields: Object.keys(optimized).length,
        step: currentStep
      });
      
      return optimized;
      
    } catch (error) {
      console.error('❌ Error applying optimized array solution:', error);
      return fields;
    }
  }

  /**
   * ✅ NEW: Helper function to update Daivesteps structure directly
   */
  updateDaivestepsField(conversationContext, stepKey, fieldPath, value) {
    try {
      if (!conversationContext) {
        console.log('⚠️ No conversationContext provided, cannot update field');
        return;
      }

      // Ensure Daivesteps exists; initialize if missing
      if (!conversationContext.Daivesteps) {
        console.log('⚠️ No Daivesteps structure found, initializing complete structure...');
        this.syncSlotsWithConversationContext(conversationContext);
        if (!conversationContext.Daivesteps) {
          // Fallback minimal structure if sync failed
          conversationContext.Daivesteps = {};
        }
      }

      const step = conversationContext.Daivesteps[stepKey];
      if (!step) {
        // Create minimal step container if missing
        conversationContext.Daivesteps[stepKey] = { slots: {} };
      }

      if (!conversationContext.Daivesteps[stepKey].slots) {
        conversationContext.Daivesteps[stepKey].slots = {};
      }

      // Handle nested field paths (e.g., 'VehicleSelection.type')
      const pathParts = fieldPath.split('.');
      let current = conversationContext.Daivesteps[stepKey].slots;
      
      for (let i = 0; i < pathParts.length - 1; i++) {
        const key = pathParts[i];
        if (!current[key]) {
          current[key] = {};
        }
        current = current[key];
      }
      
      // Set the final value
      const finalKey = pathParts[pathParts.length - 1];
      current[finalKey] = value;
      
      const valueStr = typeof value === 'object' ? JSON.stringify(value) : value;
      console.log(`✅ Updated Daivesteps: ${stepKey}.${fieldPath} = ${valueStr}`);
      console.log(`🔍 DEBUG: updateDaivestepsField called with stepKey=${stepKey}, fieldPath=${fieldPath}, value=${valueStr}`);
    } catch (error) {
      console.error('❌ Error updating Daivesteps field:', error);
    }
  }


  updateCustomerPreferences(conversationContext, extractedFields) {
    try {
      // Initialize preferences if they don't exist
      if (!this.getPreferences(conversationContext)) {
        this.updatePreferences(conversationContext, {});
      }
      
      // Update preferences with extracted fields
      if (extractedFields && extractedFields.fields && typeof extractedFields.fields === 'object') {
        // Ensure preferences exist before updating
        if (!this.getPreferences(conversationContext)) {
          this.updatePreferences(conversationContext, {});
        }
        this.updatePreferences(conversationContext, extractedFields.fields);
      } else {
        console.log('⚠️ No valid extracted fields to update customer preferences');
        return;
      }
      
      // Update step-specific data in Daivesteps structure
      if (!extractedFields || !extractedFields.fields || typeof extractedFields.fields !== 'object') {
        console.log('⚠️ No extracted fields to update customer preferences');
        return;
      }
      
      // Ensure extractedFields.fields is not null or undefined
      if (!extractedFields.fields || typeof extractedFields.fields !== 'object') {
        console.log('⚠️ extractedFields.fields is null or not an object');
        return;
      }
      
      const currentStep = extractedFields.step;
      const stepKey = `Step ${this.getStepNumber(currentStep)} - ${this.getStepDisplayName(currentStep)}`;
      
      if (!conversationContext.Daivesteps) {
        conversationContext.Daivesteps = {};
      }
      
      if (!conversationContext.Daivesteps[stepKey]) {
        conversationContext.Daivesteps[stepKey] = { slots: {} };
      }
      
      // Update step slots with extracted fields
      if (extractedFields && extractedFields.fields && typeof extractedFields.fields === 'object') {
        Object.assign(conversationContext.Daivesteps[stepKey].slots, extractedFields.fields);
      }
      
      // Mark step as having data
      conversationContext.Daivesteps[stepKey].hasData = true;
      conversationContext.Daivesteps[stepKey].lastUpdated = new Date().toISOString();
      
      console.log(`✅ Updated customer preferences for ${currentStep}:`, extractedFields.fields);
      
    } catch (error) {
      console.error('❌ Error updating customer preferences:', error);
    }
  }

