  /**
   * ✅ NEW: Check if we have enough information to proceed with inventory search
   */
  checkIfReadyForInventory(conversationContext, currentStep) {
    try {
      // ✅ SIMPLIFIED: Use conversationContext directly instead of getUnifiedSlots
      const budget = conversationContext.Daivesteps?.[2]?.slots?.budget || {};
      const vehicleSelection = conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection || {};
      const preferences = this.getPreferences(conversationContext);
      const currentSlots = {
        budget: budget,
        vehicle: vehicleSelection,
        preferences: preferences,
        currentStep: currentStep
      };
      
      // Define minimum requirements for inventory search based on journey step (simplified to only budget and vehicle_type)
      const inventoryRequirements = {
        'inquiry': ['vehicle_type'],
        'lead_capture': ['budget', 'vehicle_type'],
        'vehicle_selection': ['budget', 'vehicle_type'],
        'test_drive': ['budget', 'vehicle_type'],
        'trade_evaluation': ['budget', 'vehicle_type'],
        'qualification': ['budget', 'vehicle_type'],
        'purchase_commitment': ['budget', 'vehicle_type'],
        'vehicle_preparation': ['budget', 'vehicle_type'],
        'finance_manager': ['budget', 'vehicle_type'],
        'delivery': ['budget', 'vehicle_type'],
        'csi_followup': ['budget', 'vehicle_type']
      };
      
      const requiredFields = inventoryRequirements[currentStep] || [];
      
      // Check if all required fields are present
      for (const field of requiredFields) {
        const hasField = this.hasSlotValue(currentSlots, field) || 
                        this.hasSlotValue(preferences, field) ||
                        this.hasSlotValue(conversationContext, field);
        
        if (!hasField) {
          console.log(`⚠️ Missing required field for inventory: ${field}`);
          return false;
        }
      }
      
      console.log(`✅ All required fields present for inventory search in ${currentStep}`);
      return true;
      
    } catch (error) {
      console.error('❌ Error checking inventory readiness:', error);
      return false;
    }
  }

  /**
   * ✅ NEW: Handle vehicle rejection according to CrewAI Journey Rules
   * Resets appropriate steps while preserving essential information
   */
  handleVehicleRejection(userMessage, conversationContext) {
    try {
      const messageLower = userMessage.toLowerCase();
      const rejectionPatterns = [
        'no', 'not interested', 'don\'t like', 'not for me', 'pass',
        'not what i\'m looking for', 'not right', 'not suitable',
        'too expensive', 'too small', 'too big', 'not my style'
      ];
      
      const isRejection = rejectionPatterns.some(pattern => 
        messageLower.includes(pattern)
      );
      
      if (!isRejection) {
        return { isRejection: false };
      }
      
      // ✅ SIMPLIFIED: Use conversationContext directly instead of getUnifiedSlots
      const budget = conversationContext.Daivesteps?.[2]?.slots?.budget || {};
      const vehicleSelection = conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection || {};
      const preferences = conversationContext.Daivesteps?.[3]?.slots?.customerPreferences || {};
      const currentSlots = {
        budget: budget,
        vehicle: vehicleSelection,
        inventory_choice: conversationContext.Daivesteps?.[3]?.slots?.inventory_choice || {},
        preferences: preferences
      };
      
      // Store rejected vehicle if available
      if (currentSlots.vehicle || currentSlots.inventory_choice) {
        const rejectedVehicle = currentSlots.vehicle || currentSlots.inventory_choice;
        if (!this.getVehicleArrays(conversationContext).rejectedVehicles) {
          this.getVehicleArrays(conversationContext).rejectedVehicles = [];
        }
        this.getVehicleArrays(conversationContext).rejectedVehicles.push({
          ...rejectedVehicle,
          rejectionReason: userMessage,
          rejectedAt: new Date().toISOString()
        });
      }
      
      // Reset vehicle selection steps
      const stepsToReset = [
        'vehicle_selection',
        'test_drive',
        'purchase_commitment',
        'delivery',
        'finance'
      ];
      
      // Preserve essential information
      const preservedInfo = {
        budget: currentSlots.budget,
        vehicleCondition: currentSlots.vehicle_condition,
        preferredFeatures: currentSlots.features,
        customerPreferences: currentSlots.preferences
      };
      
      // Reset conversation context
      conversationContext.currentJourneyStep = 'vehicle_selection';
      conversationContext.vehicle = null;
      conversationContext.inventory_choice = null;
      this.getVehicleArrays(conversationContext).selectedVehicles = [];
      
      // Restore preserved information
      Object.assign(conversationContext, preservedInfo);
      
      console.log('🔄 Vehicle rejected - resetting to vehicle selection with preserved info');
      
      return {
        isRejection: true,
        stepsReset: stepsToReset,
        preservedInfo: preservedInfo,
        nextStep: 'vehicle_selection'
      };
      
    } catch (error) {
      console.error('❌ Error handling vehicle rejection:', error);
      return { isRejection: false };
    }
  }

