  /**
   * Extract features from conversation context and user message
   */
  extractFeaturesFromContext(conversationContext, userMessage) {
    try {
      const features = [];
      
      // Check preferences first
      if (this.getPreferences(conversationContext)?.features && Array.isArray(this.getPreferences(conversationContext).features)) {
        features.push(...this.getPreferences(conversationContext).features);
      }
      
      // Extract features from user message
      const messageLower = userMessage.toLowerCase();
      
      // Common feature keywords
      const featureKeywords = {
        'sunroof': ['sunroof', 'moonroof', 'panoramic', 'power sunroof', 'power moonroof'],
        'fast-charging': ['fast-charging', 'fast charging', 'dc fast', 'dc fast charging', 'quick charge'],
        'electric': ['electric', 'ev', 'hybrid', 'plug-in', 'battery'],
        'hybrid': ['hybrid', 'hybrid-electric', 'plug-in hybrid', 'gas-electric'],
        '7-seater': ['7-seater', '7 seats', 'third row', '3rd row', 'seven seats', '7 passenger'],
        'safety': ['safety', 'safety features', 'advanced safety', 'driver assistance'],
        'technology': ['technology', 'tech', 'advanced tech', 'smart features'],
        'leather': ['leather', 'leather seats', 'premium interior', 'luxury interior'],
        'awd': ['awd', 'all-wheel drive', '4wd', 'four-wheel drive'],
        'navigation': ['navigation', 'gps', 'satellite navigation', 'nav system']
      };
      
      // Check for feature mentions in user message
      for (const [feature, keywords] of Object.entries(featureKeywords)) {
        if (keywords.some(keyword => messageLower.includes(keyword))) {
          features.push(feature);
        }
      }
      
      // Check for specific feature mentions
      if (messageLower.includes('sunroof') || messageLower.includes('moonroof')) {
        features.push('sunroof');
      }
      
      if (messageLower.includes('fast-charging') || messageLower.includes('quick charge')) {
        features.push('fast-charging');
      }
      
      if (messageLower.includes('electric') || messageLower.includes('ev')) {
        features.push('electric');
      }
      
      if (messageLower.includes('hybrid')) {
        features.push('hybrid');
      }
      
      if (messageLower.includes('7') && messageLower.includes('seat')) {
        features.push('7-seater');
      }
      
      console.log('🔍 Extracted features from context:', features);
      return features;
      
    } catch (error) {
      console.warn('⚠️ Failed to extract features from context:', error.message);
      return [];
    }
  }


  /**
   * MINIMAL fallback extraction for critical slots only
   * Used when NLP extraction fails - extracts only essential information
   */
  async extractCriticalSlotsOnly(userMessage, conversationContext) {
    const slots = {};
    const message = userMessage.toLowerCase();
    
    // Only extract critical slots that are absolutely necessary
    console.log('🔧 Using minimal critical slot extraction fallback...');
    
    // 1. Vehicle Type (critical)
    if (message.includes('suv') || message.includes('s.u.v')) {
      slots.vehicle_type = 'SUV';
    } else if (message.includes('sedan') || message.includes('car')) {
      slots.vehicle_type = 'sedan';
    } else if (message.includes('truck')) {
      slots.vehicle_type = 'truck';
    }
    
    // 2. Vehicle Condition (critical)
    if (message.includes('new') || message.includes('brand new')) {
      slots.vehicle_condition = 'new';
    } else if (message.includes('pre-owned') || message.includes('preowned') || message.includes('used')) {
      slots.vehicle_condition = 'pre-owned';
    } else if (message.includes('certified')) {
      slots.vehicle_condition = 'certified';
    }
    
    // 3. Budget (critical)
    const budgetMatch = message.match(/\$?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)\s*(?:k|thousand|max)?/i);
    if (budgetMatch) {
      const budgetValue = parseInt(budgetMatch[1].replace(/,/g, ''));
      if (budgetValue > 1000 && budgetValue < 200000) { // Reasonable car price range
        slots.budget = {
          target_price: budgetValue,
          has_budget: true,
          budget_provided_at: new Date().toISOString(),
          budget_source: 'user_message'
        };
      }
    }
    
    // 4. Make (critical)
    if (message.includes('hyundai')) {
      slots.make = 'Hyundai';
    } else if (message.includes('honda')) {
      slots.make = 'Honda';
    } else if (message.includes('toyota')) {
      slots.make = 'Toyota';
    } else if (message.includes('ford')) {
      slots.make = 'Ford';
    } else if (message.includes('kia')) {
      slots.make = 'Kia';
    } else if (message.includes('chevrolet') || message.includes('chevy')) {
      slots.make = 'Chevrolet';
    } else if (message.includes('nissan')) {
      slots.make = 'Nissan';
    } else if (message.includes('mazda')) {
      slots.make = 'Mazda';
    } else if (message.includes('subaru')) {
      slots.make = 'Subaru';
    } else if (message.includes('volkswagen') || message.includes('vw')) {
      slots.make = 'Volkswagen';
    }
    
    // 5. Model (critical)
    if (message.includes('tucson')) {
      slots.model = 'Tucson';
    } else if (message.includes('santa fe') || message.includes('santafe')) {
      slots.model = 'Santa Fe';
    } else if (message.includes('civic')) {
      slots.model = 'Civic';
    } else if (message.includes('accord')) {
      slots.model = 'Accord';
    } else if (message.includes('rav4')) {
      slots.model = 'RAV4';
    }
    
    console.log('🔧 Minimal critical slots extracted:', slots);
    return slots;
  }

